import { Book } from "@/lib/types";

export const _1chronicles: Book = {
  id: "1chronicles",
  name: "1. Chronik",
  shortName: "1Chr",
  testament: "old",
  introduction: `David, wie er Gott gefällt\nIn der hebräischen Bibel bilden die beiden Chronikbücher ein einziges Werk, das an den Schluss des hebräischen Kanons gestellt wurde, um ihm besonderes Gewicht zu verleihen. Das Werk beginnt mit der Schöpfung und schließt mit dem Ende der babylonischen Gefangenschaft, konzentriert sich aber vor allem auf die Geschichte der jüdischen Könige. Es ist fast ausschließlich eine Bearbeitung aus vorhandenem Quellenmaterial. Damit sollte den aus dem Exil heimgekehrten Juden eine geistliche Orientierung durch Rückbesinnung auf die Vergangenheit gegeben werden.\n**Das erste Buch der Chronik** beginnt bei Adam und enthält viele Geschlechtsregister, um sicher nachweisen zu können, welche Familien in diesem zweiten Staat vertreten waren. Denn Gottes Erlösungsplan war an sie gebunden.\nEs gibt eine Anzahl Argumente dafür, dass der Priester Esra beide Bücher um 430 v.Chr. zusammengestellt hat.\n****Wie die Ahnentafeln von David und seinem Volk aussehen, welche Menschen dem König beistanden und wie David mit Gott lebte.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Adam, Set, Enosch,", heading: "1-9: Davids Haus\nDavids Vaterhaus (1-3)\nVon Adam bis Noah" },
      { number: 2, text: "Kenan, Mahalalel, Jered," },
      { number: 3, text: "Henoch, Metuschelach, Lamech," },
      { number: 4, text: "Noah. Noah hatte drei Söhne: Sem, Ham und Jafet." },
      { number: 5, text: "Die Söhne Jafets waren: Gomer, Magog, Madai, Jawan, Tubal, Meschech und Tiras.", heading: "Die Jafetiten" },
      { number: 6, text: "Von Gomer stammen ab: Aschkenas, Rifat und Togarma." },
      { number: 7, text: "Von Jawan: Elischa, Tarschisch, die Kittäer und die Rodaniter." },
      { number: 8, text: "Die Söhne Hams waren: Kusch, Mizrajim, Put und Kanaan.", heading: "Die Hamiten" },
      { number: 9, text: "Von Kusch stammen ab: Seba, Hawila, Sabta, Ragma und Sabtecha. Von Ragma: Saba und Dedan." },
      { number: 10, text: "Kusch zeugte auch Nimrod, den ersten Gewaltherrscher auf der Erde." },
      { number: 11, text: "Mizrajim war der Stammvater der Luditer, Anamiter, Lehabiter, Naftuhiter," },
      { number: 12, text: "Patrositer, Kasluhiter sowie der Kaftoriter, von denen die Philister herkommen." },
      { number: 13, text: "Die Nachkommen Kanaans waren: Sidon, sein Erstgeborener, und Het," },
      { number: 14, text: "außerdem die Jebusiter, Amoriter, Girgaschiter," },
      { number: 15, text: "Hiwiter, Arkiter, Siniter," },
      { number: 16, text: "Arwaditer, Zemariter und Hamatiter." },
      { number: 17, text: "Die Söhne Sems waren: Elam, Assur, Arpachschad, Lud, Aram, Uz, Hul, Geter und Meschech.", heading: "Die Semiten" },
      { number: 18, text: "Arpachschad zeugte Schelach, Schelach zeugte Eber." },
      { number: 19, text: "Eber wurden zwei Söhne geboren, einer hieß Peleg, Teilung, weil zu seiner Zeit die Erde geteilt wurde*, sein Bruder Joktan.", footnotes: ["geteilt wurde. Das wird meist im Sinn einer Aufteilung der Erde unter die Völker verstanden, wie sie in 1. Mose 11 berichtet ist. Manche sehen hier aber auch einen Hinweis auf den Beginn der geologischen Kontinentalverschiebung, was durch neuere Modellrechnungen plausibel gemacht werden kann."] },
      { number: 20, text: "Joktans Nachkommen waren: Almodad, Schelef, Hazarmawet, Jerach," },
      { number: 21, text: "Hadoram, Usal, Dikla," },
      { number: 22, text: "Obal, Abimaël, Saba," },
      { number: 23, text: "Ofir, Hawila und Jobab. Sie alle sind Nachkommen Joktans." },
      { number: 24, text: "Sem, Arpachschad, Schelach,", heading: "Von Sem bis Abraham" },
      { number: 25, text: "Eber, Peleg, Regu," },
      { number: 26, text: "Serug, Nahor, Terach," },
      { number: 27, text: "Abram, der später Abraham genannt wurde." },
      { number: 28, text: "Die Söhne Abrahams waren Isaak und Ismaël." },
      { number: 29, text: "Es folgt das Verzeichnis ihrer Nachkommen*: Ismaëls Erstgeborener war Nebajot, dann folgten Kedar, Adbeel, Mibsam,", heading: "Die Nachkommen Ismaëls", footnotes: ["Nachkommen. Hebräisch toledot, siehe 1. Mose 2,4."] },
      { number: 30, text: "Mischma, Duma, Massa, Hadad, Tema," },
      { number: 31, text: "Jetur, Nafisch und Kedma. Sie alle waren Nachkommen Ismaëls." },
      { number: 32, text: "Auch von seiner Nebenfrau Ketura hatte Abraham Söhne. Sie gebar Simran, Jokschan, Medan, Midian, Jischbak und Schuach. Die Söhne von Jokschan waren Saba und Dedan.", heading: "Die Nachkommen Keturas" },
      { number: 33, text: "Die Söhne von Midian waren Efa, Efer, Henoch, Abida und Eldaga. Sie alle waren Nachkommen Keturas." },
      { number: 34, text: "Abrahams Sohn Isaak hatte zwei Söhne: Esau und Israel*.", heading: "Die Nachkommen Esaus", footnotes: ["Israel hieß ursprünglich Jakob (1. Mose 32,28-29)."] },
      { number: 35, text: "Die Söhne von Esau waren: Elifas, Reguël, Jëusch, Jalam und Korach." },
      { number: 36, text: "Die Söhne von Elifas waren: Teman, Omar, Zefo, Gatam, Kenas, Timna und Amalek." },
      { number: 37, text: "Die Söhne Reguëls: Nahat, Serach, Schamma und Misa." },
      { number: 38, text: "Die Söhne von Seïr waren: Lotan, Schobal, Zibon, Ana, Dischon, Ezer und Dischan." },
      { number: 39, text: "Die Söhne Lotans: Hori und Hemam. Lotans Schwester war Timna." },
      { number: 40, text: "Die Söhne Schobals: Alwan, Manahat, Ebal, Schefi und Onam. Die Söhne Zibons: Aja und Ana." },
      { number: 41, text: "Der Sohn von Seïrs Sohn Ana war Dischon. Die Söhne von Seïrs Sohn Dischon: Hemdan, Eschban, Jitran und Keran." },
      { number: 42, text: "Die Söhne Ezers waren Bilhan, Saawan und Akan. Die Söhne Dischans: Uz und Aran." },
      { number: 43, text: "Bevor es in Israel einen König gab, herrschten folgende Könige über das Land Edom: Zuerst war es Bela, der Sohn Beors, in der Stadt Dinhaba.", heading: "Die Könige von Edom" },
      { number: 44, text: "Nach dem Tod Belas wurde Jobab, der Sohn Serachs, aus der Stadt Bozra König." },
      { number: 45, text: "Nach dem Tod Jobabs wurde Huscham aus dem Gebiet des Stammes Teman König." },
      { number: 46, text: "Nach dem Tod Huschams wurde Hadad, der Sohn Bedads, in der Stadt Awit König. Er besiegte die Midianiter in einer Schlacht auf dem Gebiet von Moab." },
      { number: 47, text: "Nach seinem Tod wurde Samla aus der Stadt Masreka König." },
      { number: 48, text: "Als Samla starb, wurde Schaul aus der Stadt Rehobot am Fluss König." },
      { number: 49, text: "Als Schaul starb, wurde Baal-Hanan, der Sohn Achbors König." },
      { number: 50, text: "Nach dem Tod Baal-Hanans wurde Hadad in der Stadt Pagu König. Seine Frau Mehetabel war eine Tochter Matreds und Enkelin Me-Sahabs." },
      { number: 51, text: "Als Hadad starb, gab es folgende Stammesfürsten in Edom: Timna, Alwa, Jetet," },
      { number: 52, text: "Oholibama, Ela, Pinon," },
      { number: 53, text: "Kenas, Teman, Mibzar," },
      { number: 54, text: "Magdiël und Iram. Das waren die Fürsten Edoms." },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Die Söhne Israels waren: Ruben, Simeon, Levi, Juda, Issachar, Sebulon,", heading: "Die Söhne Jakobs (Israels)" },
      { number: 2, text: "Dan, Josef, Benjamin, Naftali, Gad und Ascher." },
      { number: 3, text: "Die Söhne Judas waren: Er, Onan und Schela. Diese drei hatte ihm die Tochter von Schua, eine Kanaaniterin, geboren. Aber Er, sein Erstgeborener, tat, was Jahwe missfiel, und Jahwe ließ ihn sterben.*", heading: "Die Nachkommen Judas", footnotes: ["... sterben. Siehe 1. Mose 38,1-11."] },
      { number: 4, text: "Judas Schwiegertochter Tamar gebar ihm dann noch Perez und Serach. Insgesamt hatte Juda fünf Söhne." },
      { number: 5, text: "Die Söhne von Perez waren: Hezron und Hamul." },
      { number: 6, text: "Die Söhne Serachs: Simri, Etan, Heman, Kalkol und Darda, insgesamt fünf." },
      { number: 7, text: "Karmi hatte einen Sohn namens Achan, der Israel ins Unglück stürzte, weil er sich an Gütern vergriff, die mit einem Bann belegt waren.*", footnotes: ["Bann belegt waren. Vergleiche Josua 6-7!"] },
      { number: 8, text: "Etan hatte einen Sohn namens Asarja." },
      { number: 9, text: "Die Söhne, die Hezron geboren wurden, waren Jerachmeël, Ram und Kaleb.*", footnotes: ["... Kaleb. Die in diesem Abschnitt genannten Namen wurden aus mehreren Generationen repräsentativ ausgewählt."] },
      { number: 10, text: "Ram zeugte Amminadab, Amminadab zeugte Nachschon, das Oberhaupt des Stammes Juda.", heading: "Die Nachkommen Rams" },
      { number: 11, text: "Nachschon zeugte Salmon, Salmon Boas," },
      { number: 12, text: "Boas Obed, Obed Isai." },
      { number: 13, text: "Isai zeugte als Erstgeborenen Eliab, danach als zweiten Abinadab, als dritten Schima," },
      { number: 14, text: "als vierten Netanel, als fünften Raddai," },
      { number: 15, text: "als sechsten Ozem, als siebten David." },
      { number: 16, text: "Die sieben hatten als Schwestern Zeruja und Abigal. Zeruja hatte drei Söhne: Abischai, Joab und Asaël." },
      { number: 17, text: "Abigal gebar Amasa, dessen Vater der Ismaëlit Jeter war." },
      { number: 18, text: "Kaleb, der Sohn Hezrons, zeugte Söhne mit Asuba, seiner Frau, und mit Jeriot. Deren Söhne waren Jescher, Schobab und Ardon.", heading: "Die Nachkommen Kalebs" },
      { number: 19, text: "Nach Asubas Tod verheiratete Kaleb sich mit Efrat, die gebar ihm Hur." },
      { number: 20, text: "Hur zeugte Uri, und Uri zeugte Bezalel." },
      { number: 21, text: "Später heiratete Kalebs Vater Hezron noch einmal im Alter von 60 Jahren. Seine Frau, eine Tochter Machirs, des Stammvaters von Gilead, gebar ihm Segub." },
      { number: 22, text: "Segub zeugte Jaïr. Ihm gehörten 23 Ortschaften im Land Gilead," },
      { number: 23, text: "die \"Zeltdörfer Jaïrs\". Aber die Geschuriter und Syrer nahmen sie ihm ab, ebenso die Stadt Kenat mit den dazugehörenden Dörfern, insgesamt 60 Orte, die alle den Nachkommen Machirs, dem Vater Gileads, gehört hatten." },
      { number: 24, text: "Nach dem Tod Hezrons in Kaleb-Efrata brachte dessen Frau Abija noch einen Sohn zu Welt. Er hieß Aschhur und gründete Tekoa." },
      { number: 25, text: "Jerachmeël, der erstgeborene Sohn Hezrons, hatte folgende Söhne: Ram, seinen Erstgeborenen, dann Buna, Oren, Ozem von Ahija.", heading: "Die Nachkommen Jerachmeëls" },
      { number: 26, text: "Er hatte noch eine zweite Frau namens Atara, die war die Mutter seines Sohnes Onam." },
      { number: 27, text: "Die Söhne seines Erstgeborenen Ram waren Maaz, Jamin und Eker." },
      { number: 28, text: "Die Söhne Onams waren Schammai und Jada. Die Söhne Schammais Nadab und Abischur." },
      { number: 29, text: "Die Frau Abischurs hieß Abihajil, sie gebar ihm Achban und Molid." },
      { number: 30, text: "Die Söhne Nadabs waren Seled und Appajim. Seled starb, ohne Kinder zu hinterlassen." },
      { number: 31, text: "Der Sohn Appajims war Jischi, der Sohn Jischis Scheschan, und der Sohn Scheschans war Achlai." },
      { number: 32, text: "Jada, der Bruder von Schammai, hatte zwei Söhne: Jeter und Jonatan. Jeter starb kinderlos." },
      { number: 33, text: "Die Söhne Jonatans waren Pelet und Sasa. Diese alle waren Nachkommen Jerachmeëls." },
      { number: 34, text: "Scheschan hatte übrigens keine Söhne, sondern nur Töchter." },
      { number: 35, text: "Eine von ihnen gab er seinem ägyptischen Sklaven Jarha zur Frau, und sie gebar ihm Attai." },
      { number: 36, text: "Von ihm stammen in direkter Linie ab: Natan, Sabad," },
      { number: 37, text: "Eflal, Obed," },
      { number: 38, text: "Jehu, Asarja," },
      { number: 39, text: "Helez, Elasa," },
      { number: 40, text: "Sismai, Schallum," },
      { number: 41, text: "Jekamja und Elischama." },
      { number: 42, text: "Die Söhne Kalebs, des Bruders von Jerachmeël, waren Mescha, sein Erstgeborener – er war der Stammvater von Sif –, und die Söhne Mareschas, des Stammvaters von Hebron.", heading: "Zweite Liste der Nachkommen Kalebs" },
      { number: 43, text: "Die Söhne Hebrons waren: Korach, Tappuach, Rekem und Schema." },
      { number: 44, text: "Schema zeugte Raham, den Stammvater von Jorkoam. Rekem zeugte Schammai," },
      { number: 45, text: "dessen Sohn war Maon, der Stammvater von Bet-Zur." },
      { number: 46, text: "Efa, eine Nebenfrau Kalebs, gebar ihm die Söhne Haran, Moza und Gases." },
      { number: 47, text: "Jahdais* Söhne waren: Regem, Jotam, Geschan, Pelet, Efa und Schaaf.", footnotes: ["Jahdai stammte vielleicht aus einer Leviratsehe, siehe 5. Mose 25,5-6."] },
      { number: 48, text: "Maacha, eine andere Nebenfrau Kalebs, gebar ihm Scheber und Tirhana," },
      { number: 49, text: "später auch Schaaf, den Stammvater von Madmanna, und Schewa, den Stammvater von Machbena und von Gibea. Kaleb hatte auch eine Tochter Achsa." },
      { number: 50, text: "Das waren die Nachkommen Kalebs: Die Söhne Hurs, des Erstgeborenen von Kalebs Frau Efrata: Schobal, der Gründer von Kirjat-Jearim," },
      { number: 51, text: "Salmon, der Stammvater von Bethlehem, und Haref, der Stammvater von Bet-Gader." },
      { number: 52, text: "Schobal, der Stammvater von Kirjat-Jearim, hatte als Nachkommen die Sippe Reaja und die Hälfte der Bewohner von Manahat." },
      { number: 53, text: "In Kirjat-Jearim wohnten die Sippen der Jeteriter, Putiter, Schumatiter und Mischraïter. Von ihnen stammten auch die Bewohner von Zora und Eschtaol ab." },
      { number: 54, text: "Die Nachkommen Salmons waren die Bewohner von Bethlehem, von Netofa und Atrot-Bet-Joab sowie die andere Hälfte der Bewohner von Manahat, die aus Zora kamen." },
      { number: 55, text: "In Jabez wohnten die Sippen der Schreiber: die Tiratiter, Schimatiter und Suchatiter. Sie gehörten alle zu den Kenitern und stammten von Hammat ab, dem Stammvater von Bet-Rechab." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Folgende Söhne wurden David in Hebron geboren: als Erstgeborener Amnon, seine Mutter war Ahinoam aus Jesreel; als zweiter Daniel, seine Mutter war Abigajil aus Karmel;", heading: "Die Nachkommen Davids" },
      { number: 2, text: "als dritter Abschalom, seine Mutter war Maacha, die Tochter des Königs Talmai von Geschur; als vierter Adonija, seine Mutter war Haggit;" },
      { number: 3, text: "als fünfter Schefatja, seine Mutter war Abital; als sechster Jitream, seine Mutter war Davids Frau Egla." },
      { number: 4, text: "Diese sechs wurden David in Hebron geboren. Dort regierte er siebeneinhalb Jahre. Danach regierte David 33 Jahre in Jerusalem." },
      { number: 5, text: "Dort wurden ihm folgende Söhne geboren: vier von Batseba, der Tochter Ammiëls: Schammua, Schobab, Natan und Salomo;" },
      { number: 6, text: "neun Söhne von anderen Frauen: Jibhar, Elischua, Elifelet," },
      { number: 7, text: "Nogah, Nefeg, Jafia," },
      { number: 8, text: "Elischama, Eljada und Elifelet." },
      { number: 9, text: "Sie alle waren rechtmäßige Söhne Davids; dazu kamen noch die Söhne der Nebenfrauen. Ihre Schwester war Tamar." },
      { number: 10, text: "Die Nachkommen und Thronerben von König Salomo in direkter Linie waren Rehabeam, Abija, Asa, Joschafat," },
      { number: 11, text: "Joram, Ahasja, Joasch," },
      { number: 12, text: "Amazja, Asarja, Jotam," },
      { number: 13, text: "Ahas, Hiskija, Manasse," },
      { number: 14, text: "Amon und Joschija." },
      { number: 15, text: "Die Söhne von Joschija: der erstgeborene Johanan, der zweite Jojakim, der dritte Zidkija, der vierte Schallum." },
      { number: 16, text: "Die Söhne von Jojakim waren Jechonja* und Zidkija.", footnotes: ["Jechonja war ein anderer Name für Jojachin."] },
      { number: 17, text: "Die Söhne von Jechonja, der in die Gefangenschaft fortgeführt wurde, waren Schealtiël," },
      { number: 18, text: "Malkiram, Pedaja, Schenazzar, Jekamja, Hoschama und Nedabja." },
      { number: 19, text: "Die Söhne von Pedaja: Serubbabel und Schimi. Die Söhne von Serubbabel: Meschullam und Hananja; ihre Schwester war Schelomit." },
      { number: 20, text: "Fünf weitere Söhne von ihm waren: Haschuba, Ohel, Berechja, Hasadja und Juschab-Hesed." },
      { number: 21, text: "Die Söhne von Hananja: Pelatja, Jesaja, Refaja, Arnan, Obadja und Schechanja." },
      { number: 22, text: "Die sechs Söhne von Schechanja: Schemaja und dessen Söhne Hattusch, Jigal, Bariach, Nearja und Schafat." },
      { number: 23, text: "Die drei Söhne von Nearja: Eljoënai, Hiskija und Asrikam." },
      { number: 24, text: "Und schließlich die sieben Söhne von Eljoënai: Hodawja, Eljaschib, Pelaja, Akkub, Johanan, Delaja und Anani." },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Die Nachkommen Judas über seinen Sohn Perez waren in direkter Linie: Hezron, Karmi, Hur, Schobal,", heading: "Davids Reich (4-9)\nDie Familien des Stammes Juda" },
      { number: 2, text: "Reaja und Jahat. Die Söhne Jahats waren: Ahumai und Lahad. Von ihnen stammten die Sippen ab, die in Zora wohnten." },
      { number: 3, text: "Die Stammväter von Etam waren: Jesreel, Jischma und Jidbasch; ihre Schwester hieß Hazlelponi." },
      { number: 4, text: "Penuël war der Stammvater von Gedor, Eser war der Vater von Huscha. Beide waren Nachkommen von Hur, dem Erstgeborenen von Kalebs Frau Efrata, dem Stammvater von Bethlehem." },
      { number: 5, text: "Aschhur, der Stammvater von Tekoa, hatte zwei Frauen: Hela und Naara." },
      { number: 6, text: "Naara gebar ihm die Söhne Ahusam, Hefer, Temni und Ahaschtari." },
      { number: 7, text: "Die Söhne von Hela waren Zeret, Zohar und Etnan." },
      { number: 8, text: "Von Koz stammten Anub und Zobeba ab sowie die Sippen Aharhels, des Sohnes Harums." },
      { number: 9, text: "Ein Mann namens Jabez war der angesehenste unter seinen Brüdern. Bei seiner Geburt hatte seine Mutter gesagt: \"Ich habe ihn mit Schmerzen geboren\", und deshalb hatte sie ihn Jabez* genannt.", footnotes: ["Jabez erinnert an das hebräische Wort für Schmerz."] },
      { number: 10, text: "Jabez rief den Gott Israels an und sagte: \"Segne mich und erweitere mein Gebiet! Steh mir bei und halte Unglück und Schmerz von mir fern!\" Diese Bitte erhörte Gott." },
      { number: 11, text: "Kelub, ein Bruder von Schuha, zeugte Mehir, den Vater von Eschton." },
      { number: 12, text: "Dessen Söhne waren Bet-Rafa, Paseach und Tehinna, der Stammvater von Ir-Nahasch. Ihre Sippen wohnten in Recha." },
      { number: 13, text: "Die Söhne von Kenas waren Otniël und Seraja, die Söhne von Otniël Hatat und Meonotai," },
      { number: 14, text: "der Sohn von Meonotai Ofra. Der Sohn von Seraja war Joab, der Stammvater des \"Tales der Bauhandwerker\". Es wurde so genannt, weil alle dort Handwerker waren." },
      { number: 15, text: "Die Söhne von Kaleb Ben-Jefunne waren Iru, Ela und Naam; der Sohn von Ela war Kenas." },
      { number: 16, text: "Die Söhne von Jehallelel waren Sif, Sifa, Tirja und Asarel." },
      { number: 17, text: "Die Söhne von Esra waren Jeter, Mered, Efer und Jalon. Jeter zeugte Mirjam, Schammai und Jischbach, den Stammvater von Eschtemoa." },
      { number: 18, text: "Seine jüdische Frau gebar ihm Jered, den Stammvater von Gedor, Heber, den Stammvater von Socho, und Jekutiël, den Stammvater von Sanoach. Die anderen Söhne waren von Bitja, einer Tochter des Pharao." },
      { number: 19, text: "Hodija heiratete eine Schwester von Naham. Deren Nachkommen waren Hagarmi, der Stammvater von Keïla, und Eschtemoa, der Maachatiter." },
      { number: 20, text: "Die Söhne Schimons waren Amnon, Rinna, Ben-Hanan und Tilon. Der Sohn von Jischi war Sohet. Auch dieser hatte einen Sohn." },
      { number: 21, text: "Von Schela Ben-Juda stammten ab: Er, der Stammvater von Lecha, und Lada, der Stammvater von Marescha, außerdem die Sippen, die in Aschbea wohnten. Sie waren Weber und stellten feines weißes Leinen her." },
      { number: 22, text: "Zu den Nachkommen Schelas gehörten auch Jokim und die Bewohner von Koseba, außerdem Joasch und Saraf, die eine Zeitlang in Moab gelebt hatten und dann wieder nach Bethlehem zurückgekehrt waren. Die Berichte darüber sind alt." },
      { number: 23, text: "Ihre Nachkommen wohnten in Netaïm und Gedera und arbeiteten dort als Töpfer in den königlichen Werkstätten." },
      { number: 24, text: "Die Söhne Simeons waren Jemuël, Jamin, Jarib, Serach und Schaul.", heading: "Der Stamm Simeon" },
      { number: 25, text: "Schauls Sohn war Schallum. Auf ihn folgten als weitere Nachkommen in dieser Linie Mibsam, Mischma," },
      { number: 26, text: "Hammuël, Sakkur und Schimi." },
      { number: 27, text: "Schimi hatte sechzehn Söhne und sechs Töchter; seine Brüder dagegen hatten nur wenige Kinder. Überhaupt war der Stamm Simeon nicht so zahlreich wie der Stamm Juda." },
      { number: 28, text: "Die Nachkommen Simeons wohnten in Beerscheba, Molada, Hazar-Schual," },
      { number: 29, text: "Baala, Ezem, Eltolad," },
      { number: 30, text: "Betuël, Horma, Ziklag," },
      { number: 31, text: "Bet-Markabot, Hazar-Susim, Bet-Biri und Schaarajim. Sie bewohnten diese Städte und die dazugehörenden Dörfer bis zu der Zeit, als David König wurde." },
      { number: 32, text: "Außerdem gehörten ihnen die fünf Städte Etam, Ajin, Rimmon, Tochen und Aschan" },
      { number: 33, text: "mit allen dazugehörenden Dörfern bis nach Baal. So steht es in den Listen ihrer Familien und Wohnorte." },
      { number: 34, text: "Ihre Sippenoberhäupter* waren Meschobab, Jamlech, Joscha, der Sohn von Amazja,", footnotes: ["Sippenoberhäupter ist aus Vers 38 vorweggenommen."] },
      { number: 35, text: "Joël, Jehu, der Sohn von Joschibja und Enkel von Seraja und Urenkel von Asiël," },
      { number: 36, text: "weiter: Eljoënai, Jaakoba, Jeschohaja, Asaja, Adiël, Jesimiël, Benaja" },
      { number: 37, text: "und Sisa, der in aufsteigender Linie von Schifi, Allon, Jedaja, Schimri und Schemaja abstammte." },
      { number: 38, text: "Diese Sippen und ihre Familien hatten sich stark vermehrt." },
      { number: 39, text: "Um neue Weideplätze für ihre Schafherden zu suchen, zogen sie deshalb in den östlichen Teil des Tales, nach Gedor zu." },
      { number: 40, text: "Dort fanden sie gute, saftige Weiden. Das Land dehnte sich nach allen Seiten weit aus, es war sicher und ruhig. Die früheren Bewohner waren Nachkommen von Noahs Sohn Ham." },
      { number: 41, text: "In der Zeit, als Hiskija König von Juda war, kamen jene Sippen und überfielen die Nachkommen Hams in ihren Zeltlagern und ebenso die Mëuniter, die dort wohnten. Sie vernichteten sie völlig und ließen sich an ihrer Stelle nieder. Sie wohnen dort bis zum heutigen Tag*.", footnotes: ["bis zum heutigen Tag.Vom Standpunkt des Verfassers aus."] },
      { number: 42, text: "Eine andere Gruppe aus dem Stamm Simeon, etwa 500 Mann, zog in das Bergland Seïr. Ihre Anführer waren Pelatja, Nearja, Refaja und Usiël, die Söhne von Jischi." },
      { number: 43, text: "Sie töteten den Rest der Amalekiter, die sich einst dorthin gerettet* hatten, ließen sich dort nieder und wohnen dort bis zum heutigen Tag.", footnotes: ["dorthin gerettet. Siehe 1. Samuel 30,17."] },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Ruben war der erste Sohn Israels. Weil er aber mit einer Nebenfrau seines Vaters geschlafen hatte, wurde sein Erstgeburtsrecht auf die beiden Söhne seines Bruders Josef übertragen. Man konnte ihn nicht dem Erstgeburtsrecht entsprechend eintragen.", heading: "Die Stämme jenseits des Jordan: Ruben" },
      { number: 2, text: "Juda war am mächtigsten unter allen Bruderstämmen und aus ihm sollte der Fürst kommen. Das Erstgeburtsrecht aber gehörte Josef." },
      { number: 3, text: "Die Söhne von Ruben, dem Erstgeborenen Israels, waren Henoch, Pallu, Hezron und Karmi." },
      { number: 4, text: "Von einem seiner Nachkommen namens Joël stammte Schemaja ab. Auf ihn folgten in direkter Linie: Gog, Schimi," },
      { number: 5, text: "Micha, Reaja, Baal" },
      { number: 6, text: "und Beera, der von dem Assyrerkönig Tiglat-Pileser in die Verbannung weggeführt wurde. Er war damals das Oberhaupt des Stammes Ruben." },
      { number: 7, text: "Weiter waren in den Verzeichnissen der Nachkommen Rubens folgende Männer mit ihren Sippen aufgeführt: als Oberhaupt Jëiël, dann Secharja" },
      { number: 8, text: "und Bela, der Sohn von Asa und Enkel von Schema aus der Sippe Joël. Der Stamm Ruben wohnte in dem Gebiet von Aroer bis Nebo und Baal-Meon" },
      { number: 9, text: "und in östlicher Richtung bis an den Rand der Wüste, die sich vom Euphrat her erstreckt. Die Nachkommen Rubens hatten große Herden im ganzen Land Gilead." },
      { number: 10, text: "In der Zeit Sauls führten sie Krieg gegen die Hagariten*, besiegten sie und besetzten ihr Wohngebiet am östlichen Rand von Gilead.", footnotes: ["Hagariten. Dieser Stammes- oder Sippenverband lebte östlich des von Israel bewohnten Gebiets im Ostjordanland. Eventuell waren es Nachkommen Hagars."] },
      { number: 11, text: "Die Nachkommen Gads wohnten angrenzend an den Stamm Ruben in der Landschaft Baschan bis nach Salcha.", heading: "Die Stämme jenseits des Jordan: Gad" },
      { number: 12, text: "Ihr Oberhaupt war Joël, an zweiter Stelle kam Schafam, dann folgten Janai und Schafat. Diese Sippen wohnten in Baschan." },
      { number: 13, text: "Dazu kamen sieben weitere Männer mit ihren Sippen: Michael, Meschullam, Scheba, Jorai, Jakan, Sia und Eber." },
      { number: 14, text: "Sie waren die Nachkommen Abihajils, des Sohnes von Huri. Abihajils weitere Vorfahren in aufsteigender Linie waren: Jaroach, Gilead, Michael, Jeschischai, Jachdo und Bus." },
      { number: 15, text: "Das Oberhaupt dieser Gruppe war Ahi, der Sohn von Abdiël und Enkel von Guni." },
      { number: 16, text: "Diese Sippen wohnten in Gilead, Baschan und in den Städten, die zu dieser Gegend gehörten; ebenso an allen Weideplätzen der Landschaft Scharon bis hin an ihre Grenzen." },
      { number: 17, text: "Sie alle wurden in der Zeit der Könige Jotam von Juda und Jerobeam von Israel in die Verzeichnisse des Stammes Gad eingetragen.*", footnotes: ["Verzeichnisse ... eingetragen. Die Liste ab Vers 11 kommt sonst in der Bibel nicht vor. Sie stammt aus der Zeit Jotams (750-732 v.Chr.) und Jerobeams (793-753 v.Chr.)."] },
      { number: 18, text: "Das Heer der Stämme Ruben und Gad und des halben Stammes Manasse, die alle im Ostjordanland wohnten, bestand aus 44 760 kriegstüchtigen Männern. Sie waren mit Schild, Schwert und Bogen bewaffnet", heading: "Der Krieg mit den Nachbarstämmen" },
      { number: 19, text: "und kämpften gegen die hagaritischen Stämme Jetur, Nafisch und Nodab." },
      { number: 20, text: "Sie setzten ihr Vertrauen auf Gott und riefen ihn um Hilfe an. Er erhörte sie und stand ihnen im Kampf zur Seite, sodass sie die Hagariter und ihre Verbündeten besiegen konnten." },
      { number: 21, text: "Sie erbeuteten von ihnen 50.000 Kamele, 250.000 Schafe und 2000 Esel und nahmen 100.000 Mann gefangen." },
      { number: 22, text: "Viele von den Gegnern waren gefallen, denn der Krieg war von Gott. Sie blieben in diesem Gebiet wohnen, bis sie selbst in die Verbannung weggeführt wurden." },
      { number: 23, text: "Die eine Hälfte des Stammes Manasse war sehr zahlreich. Seine Familien wohnten im Gebiet von Baschan bis nach Baal-Hermon und bis zum Senir- und zum Hermongebirge.", heading: "Die Stämme jenseits des Jordan: halb Manasse" },
      { number: 24, text: "Die Oberhäupter der einzelnen Sippen waren: Efer, Jischi, Eliël, Asriël, Jirmeja, Hodawja und Jachdiël. Alle diese Männer waren tapfere Krieger und geachtete Leute." },
      { number: 25, text: "Aber sie wurden Jahwe, dem Gott ihrer Vorfahren, untreu und verehrten die Götter der früheren Bewohner, die Gott vor den Israeliten vertrieben hatte." },
      { number: 26, text: "Darum gab Jahwe, der Gott Israels, dem König Pul, das heißt Tiglat-Pileser von Assyrien, den Gedanken ein, den halben Stamm Manasse wie auch die Stämme Ruben und Gad in die Verbannung zu führen. Er ließ sie nach Halach, an den Fluß Habor, nach Hara und ins Tal von Gosan bringen. Dort leben sie heute noch." },
      { number: 27, text: "Die Söhne Levis waren Gerschon, Kehat und Merari,", heading: "Der Stamm Levi: die Linie der Hohen Priester" },
      { number: 28, text: "die Söhne Kehats Amram, Jizhar, Hebron und Usiël." },
      { number: 29, text: "Die Nachkommen Amrams waren Aaron, Mose und Mirjam. Die Söhne Aarons: Nadab und Abihu, Eleasar und Itamar." },
      { number: 30, text: "Eleasar zeugte Pinhas, und Pinhas zeugte Abischua;" },
      { number: 31, text: "Abischua zeugte Bukki, und Bukki zeugte Usi;" },
      { number: 32, text: "Usi zeugte Serachja, und Serachja zeugte Merajot;" },
      { number: 33, text: "Merajot zeugte Amarja, und Amarja zeugte Ahitub;" },
      { number: 34, text: "Ahitub zeugte Zadok, und Zadok zeugte Ahimaaz;" },
      { number: 35, text: "Ahimaaz zeugte Asarja, und Asarja zeugte Johanan." },
      { number: 36, text: "Johanan zeugte Asarja, der als erster den Priesterdienst in dem Tempel ausübte, den Salomo in Jerusalem gebaut hatte." },
      { number: 37, text: "Asarja zeugte Amarja, und Amarja zeugte Ahitub;" },
      { number: 38, text: "Ahitub zeugte Zadok, und Zadok zeugte Schallum;" },
      { number: 39, text: "Schallum zeugte Hilkija, und Hilkija zeugte Asarja;" },
      { number: 40, text: "Asarja zeugte Seraja, und Seraja zeugte Jozadak." },
      { number: 41, text: "Jozadak mußte mit in die Verbannung, als Jahwe die Bewohner von Juda und Jerusalem durch Nebukadnezzar wegführen ließ." },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Die Söhne Levis waren Gerschon, Kehat und Merari,", heading: "Die Nachkommen Levis" },
      { number: 2, text: "die Söhne Gerschons: Libni und Schimi." },
      { number: 3, text: "Die Söhne Kehats waren Amram, Jizhar, Hebron und Usiël," },
      { number: 4, text: "die Söhne Meraris: Machli und Muschi.Es folgen die Sippenoberhäupter der Leviten in den Hauptlinien der Nachkommen Levis:" },
      { number: 5, text: "Die Gruppe Gerschon: Auf Gerschon folgten in absteigender Linie Libni, Jahat, Simma," },
      { number: 6, text: "Joach, Iddo, Serach und Jeotrai." },
      { number: 7, text: "Die Gruppe Kehat: Auf Kehat folgten in absteigender Linie Amminadab, Korach, Assir," },
      { number: 8, text: "Elkana, Abiasaf, Assir," },
      { number: 9, text: "Tahat, Uriël, Usija und Schaul." },
      { number: 10, text: "Die Söhne Elkanas waren Amasai, Ahimot" },
      { number: 11, text: "und Elkana. Auf diesen folgten in direkter Linie Zuf, Nahat," },
      { number: 12, text: "Eliab, Jeroham, Elkana und Samuel.*", footnotes: ["und Samuel findet sich nur in einem Teil der LXX-Handschriften."] },
      { number: 13, text: "Die Söhne Samuels waren sein Erstgeborener Joël* und der zweite Abija.", footnotes: ["Joël. So mit alten Übersetzungen. Hebräisch: Waschni."] },
      { number: 14, text: "Die Gruppe Merari: Auf Merari folgten in absteigender Linie Machli, Libni, Schimi, Usa," },
      { number: 15, text: "Schima, Haggija und Asaja." },
      { number: 16, text: "Ein Teil der Nachkommen Levis erhielt von David den Auftrag, den Chorgesang im Heiligtum Jahwes zu übernehmen, nachdem die Bundeslade dort ihren festen Platz gefunden hatte.", heading: "Die Abstammung der levitischen Sänger" },
      { number: 17, text: "Sie versahen diesen Dienst vor dem Zelt der Gottesbegegnung, bis Salomo das Haus Jahwes in Jerusalem gebaut hatte. Sie richteten sich dabei genau nach den Vorschriften." },
      { number: 18, text: "Folgende Leviten wurden mit dieser Aufgabe betraut: Zunächst Heman von den Nachkommen Kehats. Er war der Sohn Joëls und Enkel Samuels." },
      { number: 19, text: "Seine weiteren Vorfahren waren Elkana, Jeroham, Eliël, Tohu," },
      { number: 20, text: "Zuf, Elkana, Mahat, Amasai," },
      { number: 21, text: "Elkana, Joël, Asarja, Zefanja," },
      { number: 22, text: "Tahat, Assir, Abiasaf, Korach," },
      { number: 23, text: "Jizhar und Kehat, der Sohn Levis und Enkel Israels." },
      { number: 24, text: "Rechts neben Heman stand Asaf. Er war der Sohn von Berechja und ein Enkel von Schima." },
      { number: 25, text: "Seine weiteren Vorfahren waren: Michael, Maaseja, Malkija," },
      { number: 26, text: "Etni, Serach, Adaja," },
      { number: 27, text: "Etan, Simma, Schimi," },
      { number: 28, text: "Jahat und Gerschon, der Sohn Levis." },
      { number: 29, text: "Links neben Heman stand Etan von den Nachkommen Meraris. Er war der Sohn von Kischi und Enkel von Abdi. Seine weiteren Vorfahren waren: Malluch," },
      { number: 30, text: "Haschabja, Amazja, Hilkija," },
      { number: 31, text: "Amzi, Bani, Schemer," },
      { number: 32, text: "Machli, Muschi und Merari, der Sohn Levis." },
      { number: 33, text: "Die anderen Leviten, ihre Brüder, hatten den Dienst an der Wohnung, am Haus Gottes, zu verrichten." },
      { number: 34, text: "Die Nachkommen Aarons waren für den Opferdienst am Brandopferaltar und dem Räucheraltar verantwortlich. Nur sie durften die Arbeiten im Höchstheiligen verrichten und Sühnehandlungen für die Israeliten vollziehen, genauso wie es Mose, der Diener Gottes, angeordnet hatte.", heading: "Die Priester aus der Nachkommenschaft Aarons" },
      { number: 35, text: "Die Nachkommen Aarons in direkter Abstammungslinie waren Eleasar, Pinhas, Abischua," },
      { number: 36, text: "Bukki, Usi, Serachja," },
      { number: 37, text: "Merajot, Amarja, Ahitub," },
      { number: 38, text: "Zadok und Ahimaaz." },
      { number: 39, text: "Die Wohnorte und die Weideplätze für die Viehherden wurden den Nachkommen Levis durch das Los zugeteilt. Das erste Los fiel auf die Nachkommen Aarons, die zu den Nachkommen Kehats gehörten.", heading: "Die Wohnorte der Leviten" },
      { number: 40, text: "Sie erhielten im Gebiet des Stammes Juda die Stadt Hebron mit dem Weideland ringsum." },
      { number: 41, text: "Aber das Ackerland der Stadt und die dazugehörenden Dörfer bekam Kaleb, der Sohn von Jefunne." },
      { number: 42, text: "Hebron war eine von den Asylstädten für Totschläger. Außerdem erhielten die Nachkommen Aarons Libna, Jattir und Eschtemoa mit ihren Weideflächen," },
      { number: 43, text: "Holon und Debir," },
      { number: 44, text: "Aschan und Bet-Schemesch mit dem dazugehörenden Weideland." },
      { number: 45, text: "Dazu bekamen sie im Stammesgebiet von Benjamin Geba, Alemet und Anatot mit ihren Weideflächen. Insgesamt waren es dreizehn Städte." },
      { number: 46, text: "Die übrigen Sippen der Nachkommen Kehats bekamen durch das Los zehn Städte in der westlichen Hälfte des Stammesgebiets von Manasse." },
      { number: 47, text: "Die verschiedenen Sippen der Nachkommen Gerschons erhielten dreizehn Städte im Gebiet der Stämme Issachar, Ascher und Naftali sowie in der östlichen Hälfte des Stammesgebiets von Manasse, in Baschan." },
      { number: 48, text: "Die Sippen der Nachkommen Meraris bekamen durch das Los zwölf Städte im Gebiet der Stämme Ruben, Gad und Sebulon." },
      { number: 49, text: "Die Israeliten übergaben also den Nachkommen Levis diese Städte mit dem dazugehörenden Weideland." },
      { number: 50, text: "Die Priester erhielten durch das Los die bereits genannten Städte im Gebiet der Stämme Juda, Simeon und Benjamin." },
      { number: 51, text: "Die anderen Sippen der Nachkommen Kehats erhielten folgende Städte mit dem dazugehörenden Weideland: im Stammesgebiet von Efraïm" },
      { number: 52, text: "die Asylstadt Sichem im Bergland von Efraïm, weiter Geser," },
      { number: 53, text: "Kibzajim*, Bet-Horon,", footnotes: ["Kibzajim. So mit Josua 21,22. Hebräisch: Jokmeam."] },
      { number: 54, text: "Ajalon und Gat-Rimmon;" },
      { number: 55, text: "im Stammesgebiet von West-Manasse Aner und Jibleam." },
      { number: 56, text: "Die Nachkommen Gerschons bekamen folgende Städte mit dem dazugehörenden Weideland: im Gebiet von Ost-Manasse: Golan in Baschan und Aschtarot;" },
      { number: 57, text: "im Gebiet von Issachar: Kedesch, Daberat," },
      { number: 58, text: "Ramot und Anem;" },
      { number: 59, text: "im Gebiet von Ascher: Mischal, Abdon," },
      { number: 60, text: "Hukok und Rehob;" },
      { number: 61, text: "und im Gebiet von Naftali: Kedesch in Galiläa, Hammon und Kirjatajim." },
      { number: 62, text: "Die Nachkommen Meraris schließlich bekamen folgende Städte mit dem dazugehörenden Weideland: im Stammesgebiet von Sebulon: Rimmon und Tabor;" },
      { number: 63, text: "auf der Ostseite des Jordan im Stammesgebiet von Ruben: die Stadt Bezer, die gegenüber von Jericho in der Steppe liegt, dazu Jahaz," },
      { number: 64, text: "Kedemot und Mefaat;" },
      { number: 65, text: "im Stammesgebiet von Gad: Ramot in Gilead, Mahanajim," },
      { number: 66, text: "Heschbon und Jaser." },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Die Söhne Issachars waren Tola, Puwa, Jaschub und Schimron,", heading: "Der Stamm Issachar" },
      { number: 2, text: "die Söhne Tolas: Usi, Refaja, Jeriël, Jachmai, Jibsam und Schemuël. Sie waren die Oberhäupter ihrer Sippen und tüchtige Krieger. In der Zeit Davids betrug die Zahl der Nachkommen Tolas nach ihren Verzeichnissen 22.600 Mann." },
      { number: 3, text: "Usi hatte einen Sohn namens Jisrachja. Er und seine Söhne Michael, Obadja, Joël und Jischija waren insgesamt fünf Sippenoberhäupter." },
      { number: 4, text: "Sie hatten so viele Frauen und Kinder, dass ihre Sippen in der Lage waren, 36.000 Mann für das Heer zu stellen." },
      { number: 5, text: "Auch ihre Brüder aus den übrigen Sippen Issachars waren alles tüchtige Krieger. Insgesamt ergab ihre Registrierung 87.000 Mann." },
      { number: 6, text: "Benjamin hatte drei Söhne: Bela, Becher und Jediaël.", heading: "Die Stämme Benjamin und Naftali" },
      { number: 7, text: "Die Söhne Belas waren Ezbon, Usi, Usiël, Jerimot und Ir. Diese fünf waren die Oberhäupter ihrer Sippen und tüchtige Krieger. Im Verzeichnis ihrer Nachkommen waren 22.034 Mann eingetragen." },
      { number: 8, text: "Die Söhne von Becher waren Semira, Joasch, Eliëser, Eljoënai, Omri, Jerimot, Abija, Anatot und Alemet." },
      { number: 9, text: "Im Verzeichnis ihrer Nachkommen waren, nach Sippen geordnet, 20.200 kriegstüchtige Männer eingetragen." },
      { number: 10, text: "Jediaël hatte einen Sohn namens Bilhan, dessen Söhne waren Jëusch, Benjamin, Ehud, Kenaana, Setan, Tarschisch und Ahischahar." },
      { number: 11, text: "Auch sie waren Oberhäupter ihrer Sippen und tüchtige Krieger. Sie stellten im Kriegsfall 17.200 Mann für das Heer." },
      { number: 12, text: "Die Söhne von Ir waren Huppim und Schuppim. Der Sohn von Aher war Huschim." },
      { number: 13, text: "Die Söhne Naftalis waren: Jachzeel, Guni, Jezer und Schallum. Sie stammten alle von Jakobs Frau Bilha ab.*", footnotes: ["Siehe 1. Mose 46,24-25."] },
      { number: 14, text: "Manasse hatte einen Sohn namens Asriël. Seine aramäische Nebenfrau gebar ihm Machir, den Vater Gileads.", heading: "Der Stamm Manasse" },
      { number: 15, text: "Machir nahm eine Schwester von Huppim und Schuppim zur Frau, sie hieß Maacha. Sein zweiter Sohn war Zelofhad; dieser hatte nur Töchter." },
      { number: 16, text: "Maacha, die Frau Machirs, gebar einen Sohn, den sie Peresch nannte. Sein Bruder hieß Scheresch. Die Söhne von Scheresch waren Ulam und Rekem." },
      { number: 17, text: "Ulam hatte einen Sohn namens Bedan. Das sind die Nachkommen von Gilead, dem Sohn von Machir und Enkel von Manasse." },
      { number: 18, text: "Seine Schwester Molechet gebar Ischhod, Abiëser und Machla." },
      { number: 19, text: "Die Söhne von Schemida waren Achjan, Schechem, Likhi und Aniam." },
      { number: 20, text: "Efraïm hatte einen Sohn namens Schutelach, dessen Sohn war Bered, und als weitere Nachkommen in direkter Linie folgten: Tahat, Elada, Tahat", heading: "Der Stamm Efraïm" },
      { number: 21, text: "und Sabad. Außer Schutelach hatte Efraïm noch zwei Söhne namens Eser und Elad. Sie zogen aber nach Gat* hinunter, um den dortigen Bewohnern ihre Viehherden zu rauben, und wurden dabei erschlagen.", footnotes: ["Gat. Eine der fünf Philisterstädte, Heimatstadt des Goliat."] },
      { number: 22, text: "Ihr Vater Efraïm trauerte lange Zeit um sie, und seine Verwandten kamen zu ihm, um ihn zu trösten." },
      { number: 23, text: "Dann schlief er wieder mit seiner Frau, und sie wurde schwanger und gebar einen Sohn. Er nannte ihn Beria, weil er in dieser Unglückszeit seiner Familie geboren wurde.*", footnotes: ["Beria erinnert an das hebräische beraah = \"im Unglück\"."] },
      { number: 24, text: "Efraïms Tochter war Scheera. Sie ließ das untere und das obere Bet-Horon sowie Usen-Scheera erbauen." },
      { number: 25, text: "Berias Sohn war Refach, und dessen weitere Nachkommen waren Reschef, Telach, Tahan," },
      { number: 26, text: "Ladan, Ammihud, Elischama" },
      { number: 27, text: "und Nun; dessen Sohn war Josua." },
      { number: 28, text: "Der Grundbesitz, den die Nachkommen Efraïms bewohnten, umfaßte Bet-El mit den dazugehörenden Dörfern, östlich davon Naara, in westlicher Richtung Geser, und im Norden reichte er bis Sichem und Aja, jeweils mit den zugehörigen Dörfern." },
      { number: 29, text: "Im Besitz der Nachkommen von Manasse befanden sich Bet-Schean, Taanach, Megiddo und Dor, ebenfalls mit den Dörfern ringsum. Alle diese Orte wurden von den Nachkommen Josefs, den Söhnen Israels, bewohnt." },
      { number: 30, text: "Die Söhne von Ascher waren Jimna, Jischwa, Jischwi und Beria; ihre Schwester war Serach.", heading: "Der Stamm Ascher" },
      { number: 31, text: "Die Söhne von Beria waren Heber und Malkiël. Dieser war der Stammvater von Birsajit." },
      { number: 32, text: "Heber zeugte Jaflet, Schemer und Hotam sowie eine Tochter namens Schua." },
      { number: 33, text: "Die Söhne Jaflets waren Pasach, Bimhal und Aschwat." },
      { number: 34, text: "Die Söhne Schemers: Ahi, Rohga, Hubba und Aram." },
      { number: 35, text: "Und die Söhne seines Bruders Helem: Zofach, Jimna, Schelesch und Amal." },
      { number: 36, text: "Die Söhne Zofachs waren Suach, Harnefer, Schual, Beri, Jimra," },
      { number: 37, text: "Bezer, Hod, Schamma, Schilscha, Jitran und Beera." },
      { number: 38, text: "Die Söhne Jeters waren Jefunne, Pispa und Ara." },
      { number: 39, text: "Die Söhne von Ulla waren Arach, Hanniël und Rizja." },
      { number: 40, text: "Sie alle waren Nachkommen von Ascher, hervorragende Führer ihrer Sippen und tapfere Krieger. In den Listen der wehrfähigen Männer waren von den Nachkommen Aschers 26.000 Mann eingetragen." },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Benjamins Erstgeborener war Bela, sein zweiter Sohn Aschbel, der dritte Achrach,", heading: "Noch einmal der Stamm Benjamin" },
      { number: 2, text: "der vierte Noha, der fünfte Rafa." },
      { number: 3, text: "Die Söhne von Bela waren Addar, Gera, Abihud," },
      { number: 4, text: "Abischua, Naaman, Ahoach," },
      { number: 5, text: "Gera, Schefufan und Huram." },
      { number: 6, text: "Die Söhne Ehuds waren die Oberhäupter der Sippen, die in Geba wohnten und von dort nach Manahat verschleppt wurden," },
      { number: 7, text: "nämlich Naaman, Ahija und Gera. Gera war es, der sie dorthin verschleppte. Gera zeugte Usa und Ahihud." },
      { number: 8, text: "Schaharajim wohnte im Hochland von Moab, nachdem er seine Frauen Huschim und Baara verstoßen hatte." },
      { number: 9, text: "Mit seiner Frau Hodesch zeugte er Jobab, Zibja, Mescha, Malkam," },
      { number: 10, text: "Jëuz, Sacheja und Mirma. Jeder von ihnen wurde das Oberhaupt einer eigenen Sippe." },
      { number: 11, text: "Von seiner früheren Frau Huschim stammten seine Söhne Abitub und Elpaal." },
      { number: 12, text: "Die Söhne Elpaals waren: Eber, Mischam und Schemed. Dieser erbaute Ono, Lod und die dazugehörenden Orte." },
      { number: 13, text: "Die Brüder Beria und Schema waren die Oberhäupter der Sippen, die in Ajalon wohnten. Sie vertrieben die Einwohner von Gat." },
      { number: 14, text: "Ihre übrigen Brüder hießen Elpaal, Schaschak und Jeremot." },
      { number: 15, text: "Die Söhne von Beria waren: Sebadja, Arad, Eder," },
      { number: 16, text: "Michael, Jischpa und Joha. –" },
      { number: 17, text: "Sebadja, Meschullam, Hiski, Heber," },
      { number: 18, text: "Jischmerai, Jislia und Jobab waren die Söhne von Elpaal." },
      { number: 19, text: "Jakim, Sichri, Sabdi," },
      { number: 20, text: "Eliënai, Zilletai, Eliël," },
      { number: 21, text: "Adaja, Beraja und Schimrat waren die Söhne von Schimi." },
      { number: 22, text: "Jischpan, Eber, Eliël," },
      { number: 23, text: "Abdon, Sichri, Hanan," },
      { number: 24, text: "Hananja, Elam, Antotija," },
      { number: 25, text: "Jifdeja und Penuël waren die Söhne von Schaschak." },
      { number: 26, text: "Schamscherai, Scheharja, Atalja," },
      { number: 27, text: "Jaareschja, Elija und Sichri waren die Söhne von Jeroham." },
      { number: 28, text: "Sie waren die Oberhäupter der Sippen ihrer Nachkommen und wohnten in Jerusalem." },
      { number: 29, text: "In Gibeon wohnte der Stammvater* dieser Stadt; seine Frau hieß Maacha.", heading: "Die Familie Sauls", footnotes: ["Stammvater. Nach 9,35hieß er Jëiël."] },
      { number: 30, text: "Sein erstgeborener Sohn war Abdon, als weitere Söhne folgten: Zur, Kisch, Baal, Nadab," },
      { number: 31, text: "Gedor, Achjo, Secher und Miklot;" },
      { number: 32, text: "dieser hatte einen Sohn namens Schima. Auch sie ließen sich wie ihre Stammesbrüder in Jerusalem nieder." },
      { number: 33, text: "Ner zeugte Kisch und Kisch zeugte Saul. Die Söhne Sauls waren Jonatan, Malkischua, Abinadab und Eschbaal." },
      { number: 34, text: "Der Sohn Jonatans war Merib-Baal*, und dieser zeugte Micha.", footnotes: ["Merib-Baal. Anderer Name für Mefi-Boschet (2. Samuel 9,12)."] },
      { number: 35, text: "Die Söhne von Micha waren Piton, Melech, Tachrea und Ahas." },
      { number: 36, text: "Ahas zeugte Joadda, und Joadda zeugte Alemet, Asmawet und Simri. Simri zeugte Moza." },
      { number: 37, text: "Seine weiteren Nachkommen waren Bina, Rafa, Elasa und Azel." },
      { number: 38, text: "Azel hatte sechs Söhne: Asrikam, Bochru, Jischmaël, Schearja, Obadja und Hanan." },
      { number: 39, text: "Die Söhne von Azels Bruder Eschek waren Ulam, sein Erstgeborener, Jëusch, der zweite, und Elifelet, der dritte." },
      { number: 40, text: "Die Söhne Ulams waren tapfere Krieger, die den Bogen spannten. Sie hatten viele Söhne und Enkel, insgesamt 150 Mann. Alle genannten Sippen gehörten zu den Nachkommen Benjamins." },
    ] },
    { number: 9, verses: [
      { number: 1, text: "So hatte sich ganz Israel in die Stammeslisten eintragen lassen. Aufgeschrieben sind sie im Buch der Könige von Israel. Weil die Bewohner von Juda Gott untreu geworden waren, wurden sie nach Babylonien in die Verbannung geführt." },
      { number: 2, text: "Die ersten Ansiedler, die sich wieder auf ihrem Grundbesitz in ihren Städten niederließen, waren Leute aus dem Volk sowie Priester, Leviten und Tempeldiener.", heading: "Die Bewohner Jerusalems nach dem Exil" },
      { number: 3, text: "Damals ließen sich in Jerusalem folgende Leute aus den Stämmen Juda, Benjamin, Efraïm und Manasse nieder:" },
      { number: 4, text: "Aus dem Stamm Juda: Utai, der Sohn Ammihuds; er stammt über Omri, Imri und Bani von Judas Sohn Perez ab;" },
      { number: 5, text: "von den Nachkommen Schelas: Asaja, der Erstgeborene, und seine Söhne;" },
      { number: 6, text: "von den Nachkommen Serachs: Jëuël. Zusammen mit seinen Brüdern waren es 690." },
      { number: 7, text: "Aus dem Stamm Benjamin: Sallu, der Sohn Meschullams; seine weiteren Vorfahren waren Hodawja und Senua." },
      { number: 8, text: "Dazu Jibneja, der Sohn Jerohams, Ela, der Sohn von Usi und Enkel von Michri, Meschullam, der Sohn von Schefatja, dessen weitere Vorfahren Reguël und Jibnija waren." },
      { number: 9, text: "Zusammen mit ihren Brüdern und nach ihren Sippen waren es 956 Sippenoberhäupter." },
      { number: 10, text: "Von den Priestern: Jedaja, Jojarib, Jachin;" },
      { number: 11, text: "Asarja, der Sohn von Hilkija, der Fürst des Gotteshauses; seine weiteren Vorfahren waren Meschullam, Zadok, Merajot und Ahitub." },
      { number: 12, text: "Dazu Adaja, der Sohn Jerohams, dessen weitere Vorfahren Paschhur und Malkija waren; Masai, der Sohn Adiëls, dessen weitere Vorfahren Jachsera, Meschullam, Meschillemot und Immer waren." },
      { number: 13, text: "Zusammen mit ihren Brüdern waren es 1760 angesehene Männer, alle befähigt zum Dienst im Haus Gottes." },
      { number: 14, text: "Von den Leviten waren es Schemaja von der Gruppe Merari, dessen Vorfahren Haschub, Asrikam, und Haschabja waren." },
      { number: 15, text: "Dann Bakbakar, Heresch, Galal und Mattanja, der Sohn von Micha und Enkel von Sichri, ein Nachkomme Asafs;" },
      { number: 16, text: "Abda, der Sohn von Schammua und Enkel von Galal, ein Nachkomme Jedutuns; Berechja, der Sohn von Asa und Enkel von Elkana, der früher in den Siedlungen von Netofa gewohnt hatte." },
      { number: 17, text: "Dazu die Torwächter: Schallum, Akkub, Talmon und Ahiman. Ihr Oberhaupt war Schallum." },
      { number: 18, text: "Seine Sippe bewacht bis zum heutigen Tag das Königstor auf der Ostseite. Sie waren schon die Torwächter in den Lagern der Söhne Levis." },
      { number: 19, text: "Auch den Dienst als Wächter am Eingang des Zelts versahen Schallum und die Männer seiner Sippe, sämtlich Nachkommen Korachs; Schallum stammte über Kore und Abisaf von Korach ab. Seine Vorfahren hatten in der Wüste den Eingang zum Lager Jahwes bewacht." },
      { number: 20, text: "Pinhas, der Sohn Eleasars, war ihr Oberhaupt gewesen. Jahwe stand ihm bei." },
      { number: 21, text: "Secharja, der Sohn von Meschelemja, war Torhüter am Eingang vom Zelt der Gottesbegegnung." },
      { number: 22, text: "Insgesamt waren es 212 Mann, die zu Torwächtern ausgewählt worden waren. Ihre Eintragung erfolgte in ihren Gehöften. David und der Seher* Samuel hatten sie in ihr Amt eingesetzt.", footnotes: ["Seher. Anderes Wort für Prophet (1. Samuel 9,9)."] },
      { number: 23, text: "Sie und ihre Söhne hatten als Wachen die Aufsicht über die Tore vom Zelthaus und später vom Haus Jahwes." },
      { number: 24, text: "Die Wachen waren nach den vier Himmelsrichtungen aufgestellt, nach Osten, Westen, Norden und Süden." },
      { number: 25, text: "Ihre Brüder, die in ihren Gehöften wohnten, mussten jeweils für sieben Tage mit ihnen zusammen zum Dienst erscheinen, wenn sie an der Reihe waren." },
      { number: 26, text: "Denn nur die vier Oberen der Torhüter waren ständig in Jerusalem. Auch sie waren Leviten. Die Leviten verwalteten außerdem die Vorratskammern und die Schätze vom Haus Gottes." },
      { number: 27, text: "Und die Nacht verbrachten sie rings um das Haus Gottes, denn ihnen war der Wachdienst übertragen, und sie mussten jeden Morgen die Tore aufschließen." },
      { number: 28, text: "Einige von ihnen hatten die Aufsicht über die Geräte für den Dienst. Abgezählt brachten sie diese hinein und abgezählt wieder heraus." },
      { number: 29, text: "Andere hatten die Aufsicht über die sonstigen Geräte und Gefäße des Heiligtums und über das Feinmehl, den Wein, das Öl, den Weihrauch und die Balsam-Öle." },
      { number: 30, text: "Aber das Mischen der Balsam-Öle zu einer Salbe war die Aufgabe der Priester." },
      { number: 31, text: "Dem Leviten Mattitja – er war der Erstgeborene Schallums aus der Nachkommenschaft Korachs – war das Pfannen-Backwerk anvertraut." },
      { number: 32, text: "Einige seiner Brüder aus der Nachkommenschaft Kehats waren für die geweihten Brote zuständig, die Sabbat für Sabbat zugerichtet werden mussten." },
      { number: 33, text: "Die levitischen Sippenoberhäupter, die für den Gesang verantwortlich waren, wohnten in den Kammern am Tempel und waren von anderen Diensten befreit, weil sie Tag und Nacht bereit sein mussten." },
      { number: 34, text: "All die genannten Sippenoberhäupter der Leviten waren in den Geschlechtsregistern aufgeführt. Sie wohnten in Jerusalem." },
      { number: 35, text: "In Gibeon wohnte Jëiël, der Stammvater dieser Stadt. Seine Frau hieß Maacha,", heading: "Die Familie Sauls" },
      { number: 36, text: "sein erstgeborener Sohn war Abdon, die anderen hießen Zur, Kisch, Baal, Ner, Nadab," },
      { number: 37, text: "Gedor, Achjo, Secher und Miklot." },
      { number: 38, text: "Miklot hatte einen Sohn namens Schima. Auch sie ließen sich wie ihre Stammesbrüder in Jerusalem nieder." },
      { number: 39, text: "Ner zeugte Kisch, und Kisch zeugte Saul. Die Söhne Sauls waren: Jonatan, Malkischua, Abinadab und Eschbaal." },
      { number: 40, text: "Jonatans Sohn war Merib-Baal und dessen Sohn Micha." },
      { number: 41, text: "Die Söhne von Micha waren: Piton, Melech, Tachrea und Ahas." },
      { number: 42, text: "Der Sohn von Ahas hieß Joadda, und dessen Söhne waren Alemet, Asmawet und Simri. Der Sohn von Simri war Moza," },
      { number: 43, text: "und als weitere Nachkommen in dieser Linie folgten Bina, Refaja, Elasa und Azel." },
      { number: 44, text: "Azel hatte sechs Söhne: Asrikam, Bochru, Jischmaël, Schearja, Obadja und Hanan." },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Zwischen den Philistern und Israel kam es zur Schlacht. Die Männer Israels mussten vor den Philistern fliehen, und viele von ihnen blieben erschlagen auf den Bergen von Gilboa liegen.", heading: "10-29: Davids Stadt\nDavids Regierungsantritt (10-12)\nSauls Niederlage und Tod" },
      { number: 2, text: "Die Philister setzten auch Saul und seinen Söhnen nach. Sie erschlugen die drei Söhne Sauls Jonatan, Abinadab und Malkischua." },
      { number: 3, text: "Um Saul herum tobte ein erbitterter Kampf. Die Bogenschützen hatten ihn getroffen und schwer verwundet." },
      { number: 4, text: "Da sagte Saul zu seinem Waffenträger: \"Zieh dein Schwert und töte mich, damit nicht diese Unbeschnittenen* kommen und ihren Spott mit mir treiben!\" Sein Waffenträger aber wollte es nicht tun, er scheute sich davor. Da nahm Saul sein Schwert und stürzte sich hinein.", footnotes: ["Unbeschnittene. Verächtlicher Ausdruck für Menschen, die nicht zum Bund Gottes gehörten. Siehe 1. Mose 17,9-14!"] },
      { number: 5, text: "Als der Waffenträger sah, dass Saul tot war, stürzte auch er sich in sein Schwert und starb neben ihm." },
      { number: 6, text: "So starben Saul, seine drei Söhne, sein Waffenträger und alle seine Männer an diesem einen Tag." },
      { number: 7, text: "Als die Israeliten der Jesreel-Ebene sahen, dass die Männer Israels geflohen und Saul und seine Söhne tot waren, verließen sie ihre Städte und flohen. Die Philister nahmen sie in Besitz und wohnten darin." },
      { number: 8, text: "Am Tag nach der Schlacht kamen die Philister, um die Gefallenen zu plündern. Dabei fanden sie Saul und seine drei Söhne auf den Bergen von Gilboa." },
      { number: 9, text: "Sie zogen Saul aus und nahmen seinen Kopf und seine Rüstung. Beides ließen sie im Land der Philister herumzeigen, um die Freudenbotschaft in ihren Götzentempeln und unter dem Volk zu verkünden." },
      { number: 10, text: "Seine Rüstung legten sie in den Tempel ihres Gottes und seinen Schädel spießten sie im Haus Dagons auf." },
      { number: 11, text: "Als die Bewohner von Jabesch in Gilead* hörten, was die Philister Saul angetan hatten,", footnotes: ["Jabesch in Gilead lag 15 km südöstlich von Bet-Schean im Ostjordanland."] },
      { number: 12, text: "machten sich alle wehrfähigen Männer auf und holten die Leichen Sauls und seiner Söhne nach Jabesch. Sie begruben ihre Gebeine unter der Terebinthe von Jabesch und fasteten sieben Tage lang." },
      { number: 13, text: "So kam Saul ums Leben, weil er Jahwe untreu geworden war und das Wort Jahwes nicht beachtet hatte und auch weil er den Totengeist befragt hatte, um Rat zu holen," },
      { number: 14, text: "anstatt sich an Jahwe zu wenden. Darum ließ dieser ihn umkommen und übergab das Königtum David, dem Sohn Isais." },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Ganz Israel versammelte sich bei David in Hebron und sagte: \"Wir sind doch dein Fleisch und Blut.", heading: "David wird König über Israel" },
      { number: 2, text: "Schon früher, als Saul noch unser König war, hast du Israels Heer in den Kampf geführt und wieder heimgebracht. Und Jahwe, dein Gott, hat zu dir gesagt: 'Du sollst der Hirt meines Volkes Israel sein, du sollst Israels Fürst werden!'\"" },
      { number: 3, text: "Das sagten die Ältesten Israels, die zum König nach Hebron gekommen waren. Und König David schloss vor Jahwe einen Bund mit ihnen. Daraufhin salbten sie David zum König über Israel, wie Jahwe es durch Samuel angekündigt hatte." },
      { number: 4, text: "David zog nun mit allen Männern Israels nach Jerusalem, das damals noch Jebus hieß. Die Jebusiter waren die Bewohner des Landes.", heading: "David erobert Jerusalem" },
      { number: 5, text: "Die Einwohner von Jebus riefen David zu: \"Da wirst du nicht hineinkommen!\" Aber David nahm die Bergfestung Zion ein, und sie wurde zur Davidsstadt." },
      { number: 6, text: "David hatte gesagt: \"Wer den ersten Jebusiter erschlägt, soll Oberhaupt und Anführer werden.\" Da stieg Joab Ben-Zeruja als Erster in die Burg hinauf und wurde zum Oberhaupt." },
      { number: 7, text: "David machte die Bergfestung zu seinem Wohnsitz und nannte sie \"Davidsstadt\"." },
      { number: 8, text: "Er baute sie vom Stadtwall her ringsum aus. Joab stellte den Rest der Stadt wieder her." },
      { number: 9, text: "David wurde immer mächtiger, und Jahwe, der allmächtige Gott, stand ihm bei." },
      { number: 10, text: "Das sind die Anführer der Elitetruppe Davids, die ihm während seiner Königsherrschaft zusammen mit ganz Israel mutig beistanden, um ihn zum König zu machen, wie Jahwe es für Israel angeordnet hatte.", heading: "Davids Elitetruppe" },
      { number: 11, text: "Es folgt die Aufzählung der Elitetruppe Davids: Joschobam Ben-Hachmoni, Anführer der Offiziere. Er schwang seinen Speer über 300 Mann, die er in einer Schlacht durchbohrt hatte." },
      { number: 12, text: "Der zweite nach ihm war Eleasar Ben-Dodo, ein Nachkomme Ahoachs. Er gehörte zu den drei Helden der Elitetruppe." },
      { number: 13, text: "Er war dabei, als die Philister sich bei Pas-Dammim zum Kampf gegen David sammelten. Dort war ein Feldstück mit Gerste. Als das Volk vor den Philistern floh," },
      { number: 14, text: "stellten sie sich mitten auf das Feld, entrissen es den Philistern und schlugen sie. So schaffte Jahwe eine große Rettung." },
      { number: 15, text: "Drei von den dreißig Helden gingen einmal zu dem Felsen hinunter, wo sich David befand, in der Höhle bei Adullam. Die Philister hatten die Ebene Refaïm besetzt." },
      { number: 16, text: "Auch in Bethlehem lagen sie. David hielt sich gerade in der Bergfestung auf," },
      { number: 17, text: "als ihn ein großes Verlangen überkam. Er sagte: \"Wer bringt mir Wasser aus der Zisterne am Tor von Bethlehem?\"" },
      { number: 18, text: "Da drangen die drei Helden ins Lager der Philister ein, schöpften Wasser aus der Zisterne am Tor von Bethlehem und brachten es zu David. Doch David wollte es nicht trinken, sondern goss es als Trankopfer vor Jahwe aus." },
      { number: 19, text: "Er sagte: \"Jahwe bewahre mich davor, so etwas zu tun! Das wäre, als wollte ich das Blut dieser Männer trinken, die unter Lebensgefahr hingegangen sind. Sie haben ihr Leben eingesetzt, um mir das Wasser zu bringen.\" Deshalb wollte er es nicht trinken. Das hatten die drei Helden getan." },
      { number: 20, text: "Abischai, der Bruder Joabs, war der Anführer der Dreißig. 300 Feinde hatte er mit dem Speer getötet, und er war angesehen unter den Dreien." },
      { number: 21, text: "Von den Dreien der zweiten Reihe* war er der berühmteste, sodass er ihr Anführer wurde, doch an die ersten Drei reichte er nicht heran.", footnotes: ["zweiten Reihe. Wahrscheinlich gab es mehr als eine Dreiergruppe berühmter Soldaten."] },
      { number: 22, text: "Benaja Ben-Jojada aus Kabzeel war ein tapferer Mann, der große Taten vollbrachte. Er erschlug die beiden Kriegshelden von Moab. Und an einem Schneetag stieg er in eine Zisterne und erschlug den Löwen, der dort hineingeraten war." },
      { number: 23, text: "Er war es auch, der den zweieinhalb Meter* großen Ägypter erschlug, der einen Speer wie einen Weberbaum in der Hand hatte. Mit einem Stock ging er zu dem Ägypter hinunter, riss ihm den Speer aus der Hand und durchbohrte ihn damit.", footnotes: ["zweieinhalb Meter. Wörtlich: fünf Ellen. Weil die für eine Elle angegebenen Maße zwischen 44,42 und 52,45 cm schwanken, gehen wir für die Umrechnungen von 50 cm aus."] },
      { number: 24, text: "Solche Taten vollbrachte Benaja Ben-Jojada. Er war hochgeachtet unter den dreißig Helden" },
      { number: 25, text: "und wurde mehr als sie geehrt. Aber an die Drei reichte er nicht heran. David machte ihn zum Anführer seiner Leibgarde." },
      { number: 26, text: "Zur Elitetruppe gehörten Asaël, der Bruder von Joab; Elhanan Ben-Dodo aus Bethlehem," },
      { number: 27, text: "Schammot aus Harod, Helez, ein Peloniter;" },
      { number: 28, text: "Ira Ben-Ikkesch aus Tekoa, Abiëser aus Anatot," },
      { number: 29, text: "Sibbechai aus Huscha, Ilai aus Ahoach," },
      { number: 30, text: "Mahrai und Heled Ben-Baana aus Netofa," },
      { number: 31, text: "Ittai Ben-Ribai aus Gibea im Gebiet Benjamins, Benaja aus Piraton," },
      { number: 32, text: "Hiddai aus Nahale-Gaasch, Abiël aus Bet-Araba," },
      { number: 33, text: "Asmawet aus Bahurim, Eljachba aus Schaalbim," },
      { number: 34, text: "Haschem* aus Gison, Jonatan Ben-Schage und", footnotes: ["Haschem. Wörtlich: Söhne des Haschem."] },
      { number: 35, text: "Ahiam Ben-Sachar aus Harar; Elifal Ben-Ur," },
      { number: 36, text: "Hefer aus Mechera, Ahija aus Pelon," },
      { number: 37, text: "Hezro aus Karmel, Naarai Ben-Esbai," },
      { number: 38, text: "Joël, der Bruder Natans; Mibhar Ben-Hagri," },
      { number: 39, text: "Zelek, der Ammoniter*, Nachrai aus Beerot, der Waffenträger Joabs;", footnotes: ["Die Ammoniter lebten nordöstlich vom Toten Meer."] },
      { number: 40, text: "Ira und Gareb aus Jattir," },
      { number: 41, text: "Urija, der Hetiter*; Sabad Ben-Achlai,", footnotes: ["Das Reich der Hetiter erstreckte sich nach Norden bis weit in die heutige Türkei."] },
      { number: 42, text: "Adina Ben-Schisa, einer der Oberen des Stammes Ruben und Anführer von dreißig Mann;" },
      { number: 43, text: "Hanan Ben-Maacha, Joschafat aus Meten," },
      { number: 44, text: "Usija aus Aschtarot, Schama und Jëiël, die Söhne Hotams aus Aroer;" },
      { number: 45, text: "Jediaël Ben-Schimri, und sein Bruder Joha aus Tiz," },
      { number: 46, text: "Eliël aus Mahanajim, Jeribai und Joschawja, die Söhne Elnaams; Jitma, der Moabiter*,", footnotes: ["Die Moabiter lebten östlich vom Toten Meer zwischen den Flüssen Arnon und Zered."] },
      { number: 47, text: "Eliël, Obed und Jaasiël aus Zoba." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Als David sich noch in Ziklag* aufhielt, um sich von König Saul Ben-Kisch fernzuhalten, schlossen sich ihm schon damals heldenhafte Männer an, um ihm in seinem Kampf zu helfen.", heading: "Davids Mitkämpfer in Ziklag", footnotes: ["Ziklag war eine Stadt im Gebiet der Philister (1. Samuel 27,6)."] },
      { number: 2, text: "Sie waren mit Bogen ausgerüstet und konnten sowohl mit der rechten als auch mit der linken Hand Steine schleudern und Pfeile schießen. Von Sauls eigenen Stammesbrüdern aus Benjamin kamen" },
      { number: 3, text: "als Oberhaupt Ahiëser und sein Bruder Joasch, die Söhne von Schemaa aus Gibea; weiter Jesiël und Pelet, die Söhne von Asmawet; Beracha und Jehu aus Anatot," },
      { number: 4, text: "Jischmaja aus Gibeon, später war er einer von den \"Dreißig\" und ihr Anführer;" },
      { number: 5, text: "Jirmeja, Jahasiël, Johanan und Josabad aus Gedera;" },
      { number: 6, text: "Elusai, Jerimot, Bealja, Schemarja und Schefatja aus Haruf;" },
      { number: 7, text: "Elkana, Jischija, Asarel, Joëser und Jaschobam von den Nachkommen Korachs;" },
      { number: 8, text: "Joëla und Sebadja, die Söhne von Jeroham, aus Gedor." },
      { number: 9, text: "Auch aus dem Stamm Gad ging eine Anzahl tapferer Männer zu David über, als er in seiner Bergfestung in der Wüste Juda war. Sie waren mit Schild und Speer bewaffnet, kampferprobt, mutig wie Löwen und in den Bergen flink wie Gazellen." },
      { number: 10, text: "Ihr Oberhaupt war Eser, der zweite Obadja, der dritte Eliab," },
      { number: 11, text: "der vierte Mischmanna, der fünfte Jirmeja," },
      { number: 12, text: "der sechste Attai, der siebte Eliël," },
      { number: 13, text: "der achte Johanan, der neunte Elsabad," },
      { number: 14, text: "der zehnte Jirmeja, der elfte Machbannai." },
      { number: 15, text: "Sie alle waren Anführer im Heer. Der Schwächste von ihnen nahm es mit hundert Gegnern auf, der Stärkste aber mit tausend." },
      { number: 16, text: "Schon im April* überschritten sie den Jordan, als er Hochwasser führte und alle Nebentäler auf beiden Seiten abgeschnitten waren.", footnotes: ["April. Wörtlich: Im 1. Monat."] },
      { number: 17, text: "Auch aus den Stämmen Benjamin und Juda kamen einige zu David in die Bergfestung." },
      { number: 18, text: "David ging zu ihnen hinaus und sagte: \"Wenn ihr als Freunde zu mir kommt, um mir zu helfen, dann seid ihr herzlich willkommen. Wenn ihr mich aber an meine Feinde verraten wollt, obwohl kein Blut an meinen Händen klebt, dann möge der Gott unserer Vorfahren es sehen und strafen.\"" },
      { number: 19, text: "Da kam der Geist Gottes über Amasai, der später das Oberhaupt der Offiziere wurde, und er rief:\"David, wir gehören zu dir, / und zu dir stehen wir, Ben-Isai! / Friede, Friede dir / und Frieden dem, der dir hilft! / Denn dir hilft dein Gott!\"Da nahm David sie auf und reihte sie unter die Oberhäupter der Streifschar ein." },
      { number: 20, text: "Auch von Manasse liefen einige Männer zu David über. Das geschah zu der Zeit, als David mit den Philistern gegen Saul in den Kampf zog. Es kam allerdings nicht dazu, denn nach einer Beratung schickten ihn die Fürsten der Philister wieder weg. Sie sagten nämlich: \"Um den Preis unserer Köpfe könnte er zu seinem früheren Herrn Saul überlaufen.\"" },
      { number: 21, text: "Als er nach Ziklag zog, liefen folgende Männer aus Manasse zu ihm über: Adnach, Josabad, Jediaël, Michael, Josabad, Elihu und Zilletai. Sie waren Oberhäupter von Heereseinheiten des Stammes Manasse gewesen." },
      { number: 22, text: "Sie halfen David im Kampf gegen die Streifschar*, denn sie waren kriegstüchtige Männer und wurden später Obere im Heer.", footnotes: ["Streifschar. Wahrscheinlich sind die Amalekiter gemeint, die Ziklag überfallen hatten (1. Samuel 30,1)."] },
      { number: 23, text: "Tag für Tag kamen Leute zu David, um ihm zu helfen, bis es ein großes Heerlager wurde, ein Heerlager Gottes." },
      { number: 24, text: "Es folgt ein Verzeichnis aller wehrfähigen Männer, die zu David nach Hebron kamen, um das Königtum Sauls nach dem Befehl Jahwes auf ihn zu übertragen.", heading: "Davids Heer in Hebron" },
      { number: 25, text: "Vom Stamm Juda waren es 6800 mit Schild und Lanze Bewaffnete," },
      { number: 26, text: "von Simeon 7100 Wehrtüchtige," },
      { number: 27, text: "von den Leviten 4600," },
      { number: 28, text: "dazu Jojada, das Oberhaupt der Nachkommen Aarons, und mit ihm 3700 Mann," },
      { number: 29, text: "sowie Zadok, ein junger tapferer Krieger mit seiner Sippe: 22 Anführer." },
      { number: 30, text: "Von den Benjaminiten, den Stammesbrüdern Sauls, kamen 3000, aber der größte Teil des Stammes hielt bis dahin treu zur Familie Sauls." },
      { number: 31, text: "Von Efraïm kamen 20.800 Wehrtüchtige, Männer, die in ihren Familien sehr geachtet wurden." },
      { number: 32, text: "Vom halben Stamm Manasse kamen 18.000 Männer, die namentlich bestimmt waren, dass sie kommen und David zum König machen sollten." },
      { number: 33, text: "Von Issachar kamen solche, die das Gebot der Stunde verstanden und wussten, was Israel zu tun hatte: 200 Anführer mit ihren Männern." },
      { number: 34, text: "Von Sebulon kamen 50.000 Mann mit einmütigem Herzen, kriegsmäßig ausgerüstet und kampfbereit, um David zu helfen." },
      { number: 35, text: "Von Naftali kamen 1000 Anführer und 37.000 Mann, mit Schild und Speer bewaffnet," },
      { number: 36, text: "von Dan 28.600 kampfbereite Männer." },
      { number: 37, text: "Von Ascher kamen 40.000 kampfbereite Wehrfähige," },
      { number: 38, text: "und vom Ostjordanland kamen von Ruben, Gad und dem halben Stamm Manasse 120.000 Mann in voller Kriegsbewaffnung." },
      { number: 39, text: "Sie alle kamen in Heeresordnung nach Hebron, mit der einmütigen Absicht, David zum König über ganz Israel zu machen. Auch alle übrigen Israeliten waren sich in diesem Wunsch einig." },
      { number: 40, text: "Drei Tage blieben sie dort bei David und aßen und tranken, denn ihre Brüder hatten alles für sie bereitgestellt." },
      { number: 41, text: "Auch die, die in ihrer Nähe lebten, bis hin zu den Stammesgebieten von Issachar, Sebulon und Naftali brachten Lebensmittel auf Eseln und Kamelen, auf Maultieren und Rindern: Mehlspeisen, Feigenkuchen, Rosinenkuchen, Wein und Öl, Rinder und Schafe in großer Zahl, denn es herrschte Freude in Israel." },
    ] },
    { number: 13, verses: [
      { number: 1, text: "David beriet sich mit den Anführern der Tausend- und Hundertschaften und mit allen Fürsten.", heading: "Die Bundeslade (13-16)\nDie erste Überführung der Bundeslade" },
      { number: 2, text: "Dann sagte er zu der ganzen Versammlung Israels: \"Wenn es euch gut erscheint und wenn es Jahwe, unserem Gott, gefällt, dann lasst uns Boten zu unseren Brüdern in alle Gegenden des Landes schicken und außerdem zu den Priestern und Leviten in ihren Wohnorten, dass sie sich bei uns versammeln." },
      { number: 3, text: "Dann wollen wir die Lade unseres Gottes zu uns herüberholen, denn in der Zeit Sauls haben wir nicht nach ihr gefragt.\"" },
      { number: 4, text: "Die ganze Versammlung stimmte dem Vorhaben zu, denn der Plan gefiel dem Volk." },
      { number: 5, text: "So brachte David ganz Israel zusammen, vom Schihor* vor Ägypten bis dorthin, wo man nach Hamat* kommt, um die Lade Gottes aus Kirjat-Jearim* zu holen.", footnotes: ["Schihor. Einer der Nilkanäle in der Nähe des heutigen Suez-Kanals.", "Hamat.Heute: Labwe, etwa 70 km nördlich vom Hermon.", "Kirjat-Jearim, \"Wälderstadt\", lag 14 km westlich von Jerusalem."] },
      { number: 6, text: "Dann zog er mit ganz Israel nach Baala* in Juda, also nach Kirjat-Jearim, um von dort die Lade Gottes nach Jerusalem zu holen, die Lade, die Jahwe geweiht ist, dem Namen des Allmächtigen, der über den Cherubim* thront.", footnotes: ["Baala in Juda ist ein anderer Name für Kirjat-Jearim, wo sich die Bundeslade während der Zeit Sauls befand (1. Samuel 7,1).", "Cherub, Mehrzahl: Cherubim. Majestätisches (Engel-)Wesen, das Gottes Herrlichkeit repräsentiert. Cherubim-Figuren waren auf dem Deckel der Bundeslade befestigt."] },
      { number: 7, text: "Auf einem neuen unbenutzten Wagen holten sie die Lade Gottes aus dem Haus Abinadabs weg. Usa und Achjo führten den Wagen." },
      { number: 8, text: "David und ganz Israel tanzten voller Hingabe vor Gott und sangen dazu unter Begleitung von Zithern und Harfen, Tamburin, Zimbeln und Trompeten." },
      { number: 9, text: "Als sie zum Dreschplatz Kidons kamen, griff Usa nach der Lade Gottes und hielt sie fest, denn die Rinder hatten sich losgerissen." },
      { number: 10, text: "Da flammte Jahwes Zorn gegen Usa auf. Er schlug ihn, weil er nach der Lade Gottes gegriffen hatte, sodass er dort vor Gott starb." },
      { number: 11, text: "Aber auch David stieg es heiß hoch, weil Jahwe Usa so aus dem Leben gerissen hatte. Darum nannte man den Platz Perez-Usa, Usas Riss, und so heißt er bis heute*.", footnotes: ["bis heute.Vom Standpunkt des Verfassers der Chronikbücher aus."] },
      { number: 12, text: "David bekam an diesem Tag Angst vor Gott und sagte: \"Wie kann ich die Lade Gottes überhaupt zu mir bringen?\"" },
      { number: 13, text: "Deshalb ließ er die Lade nicht zu sich in die Davidsstadt bringen, sondern führte sie in das Haus Obed-Edoms, der aus Gat stammte." },
      { number: 14, text: "Dort blieb die Lade Gottes drei Monate stehen. Da segnete Jahwe Obed-Edom und sein ganzes Haus." },
    ] },
    { number: 14, verses: [
      { number: 1, text: "König Hiram von Tyrus* schickte eine Gesandtschaft zu David. Er lieferte ihm Zedernholz für seinen Palast und schickte Zimmerleute und Steinmetze zum Bauen.", heading: "David in Jerusalem", footnotes: ["Tyrus war die wichtigste Hafenstadt an der phönizischen Küste, 56 km nördlich vom Berg Karmel."] },
      { number: 2, text: "Daran erkannte David, dass Jahwe ihn zum König über Israel eingesetzt hatte und aus Liebe zu seinem Volk sein Königtum zu Ansehen brachte." },
      { number: 3, text: "David nahm noch weitere Frauen in Jerusalem und bekam noch mehr Söhne und Töchter." },
      { number: 4, text: "Seine in Jerusalem geborenen Söhne waren Schammua, Schobab, Natan, Salomo," },
      { number: 5, text: "Jibhar, Elischua, Elpelet," },
      { number: 6, text: "Nogah, Nefeg, Jafia," },
      { number: 7, text: "Elischama, Beeljada und Elifelet." },
      { number: 8, text: "Als die Philister hörten, dass David zum König über Israel gesalbt worden war, kamen sie mit ihrem ganzen Heer, um David zu stellen. Sobald David das erfuhr, zog er ihnen entgegen.", heading: "Krieg mit den Philistern" },
      { number: 9, text: "Die Philister hatten sich in der Ebene von Refaïm* ausgebreitet.", footnotes: ["Die Ebene Refaïm ist ein fruchtbares Gebiet westlich von Jerusalem."] },
      { number: 10, text: "Da fragte David Gott: \"Soll ich die Philister angreifen? Wirst du sie in meine Hand geben?\" Jahwe sagte zu ihm: \"Greif sie an! Ich gebe sie in deine Gewalt!\"" },
      { number: 11, text: "Da zog David aus und besiegte die Philister bei Baal-Perazim. Er sagte: \"Wie Wasser einen Damm durchbricht, hat Gott die Reihen meiner Feinde vor mir durchbrochen.\" Deshalb nannte man jenen Ort Baal-Perazim, Herr der Durchbrüche." },
      { number: 12, text: "Die fliehenden Philister ließen sogar ihre Götzenbilder zurück. David aber befahl, sie zu verbrennen." },
      { number: 13, text: "Doch einige Zeit später kamen die Philister wieder und breiteten sich in der Ebene Refaïm aus." },
      { number: 14, text: "David fragte Gott, was er tun solle, und dieser antwortete: \"Greif sie nicht direkt an, sondern umgehe sie und fall ihnen von den Bakabäumen* her in den Rücken.", footnotes: ["Bakabaum. Vielleicht ein anderes Wort für den Maulbeerbaum (Sykomore)."] },
      { number: 15, text: "Sobald du ein Geräusch hörst, als ob jemand durch die Wipfel der Bakabäume schreitet, dann schlägst du los! Denn Gott ist vor dir her in die Schlacht gezogen, um das Heerlager der Philister zu schlagen.\"" },
      { number: 16, text: "David machte es so, wie Gott es ihm befohlen hatte. Er schlug die Philister von Gibeon bis nach Geser*.", footnotes: ["Geser. Die alte kanaanitische Königsstadt lag 27 km südöstlich von Joppe und gehörte zu dieser Zeit wahrscheinlich den Philistern."] },
      { number: 17, text: "Der Name Davids wurde in allen Ländern bekannt und Jahwe sorgte dafür, dass alle Völker ihn fürchteten." },
    ] },
    { number: 15, verses: [
      { number: 1, text: "David baute sich Häuser in der Davidsstadt. Auch für die Lade Gottes richtete er einen Platz her und schlug ein Zelt für sie auf.", heading: "Die zweite Überführung der Bundeslade" },
      { number: 2, text: "Damals sagte David: \"Niemand außer den Leviten darf die Lade Gottes tragen, denn sie hat Jahwe dazu erwählt, seine Lade zu tragen und ihm zu dienen.\"" },
      { number: 3, text: "David hatte ganz Israel nach Jerusalem zusammengerufen, um die Lade Jahwes an den Platz hinaufzubringen, den er für sie hergerichtet hatte." },
      { number: 4, text: "Dann holte er die Nachkommen Aarons und die Leviten heran." },
      { number: 5, text: "Von den Nachkommen Kehats war es Uriël mit 120 Mann;" },
      { number: 6, text: "von den Nachkommen Meraris: Asaja mit 220 Mann;" },
      { number: 7, text: "von den Nachkommen Gerschons: Joël mit 130 Mann;" },
      { number: 8, text: "von den Nachkommen Elizafans: Schemaja mit 200 Mann;" },
      { number: 9, text: "von den Nachkommen Hebrons: Eliël mit 80 Mann;" },
      { number: 10, text: "von den Nachkommen Usiëls: Amminadab mit 112 Mann." },
      { number: 11, text: "David ließ die Priester Zadok und Abjatar und die Leviten Uriël, Asaja und Joël, Schemaja und Eliël und Amminadab zu sich kommen" },
      { number: 12, text: "und sagte zu ihnen: \"Ihr seid die Oberhäupter der levitischen Familien. Heiligt euch* und eure Brüder und bringt die Lade Jahwes, des Gottes Israels, zu dem Platz hinauf, den ich für sie vorbereitet habe.", footnotes: ["Heiligt euch.Das bedeutete für die Israeliten, dass sie ihre Kleider und sich selbst waschen mussten und keinen Geschlechtsverkehr haben durften (siehe 2. Mose 19,10.14-15; 3. Mose 16,4.24)."] },
      { number: 13, text: "Weil ihr es beim ersten Mal nicht getan habt, hat Jahwe, unser Gott, eine Lücke in unsere Reihen gerissen, weil wir ihn nicht der Vorschrift entsprechend befragt hatten.\"" },
      { number: 14, text: "Da heiligten sich die Priester und die Leviten, um die Lade von Jahwe, dem Gott Israels, heraufzubringen." },
      { number: 15, text: "Die Leviten trugen die Lade Gottes auf ihren Schultern mit den Tragstangen, wie Mose es nach dem Wort Jahwes angeordnet hatte." },
      { number: 16, text: "David hatte auch den Oberhäuptern der Leviten befohlen, ihre Brüder, die Sänger, mit Musikinstrumenten, Harfen und Zithern und Zimbeln aufzubieten, damit sie laute Freudenklänge erschallen ließen." },
      { number: 17, text: "Sie beauftragten damit Heman Ben-Joël, sowie Asaf Ben-Berechja und Etan Ben-Kuschaja, der zu den Nachkommen Meraris gehörte." },
      { number: 18, text: "Hinzu kamen folgende Leviten der zweiten Ordnung: Secharja, Jaasiël, Schemiramot, Jehiël, Unni, Eliab, Benaja, Maaseja, Mattitja, Elifelehu, Mikneja, Obed-Edom und Jëiël, die Torwächter." },
      { number: 19, text: "Die Sänger Heman, Asaf und Etan ließen sich mit bronzenen Zimbeln hören." },
      { number: 20, text: "Secharja, Jaasiël, Schemiramot, Jehiël, Unni, Eliab, Maaseja und Benaja spielten Harfe in der hohen Tonlage." },
      { number: 21, text: "Mattitja, Elifelehu, Mikneja, Obed-Edom, Jëiël und Asasja spielten Laute in der tiefen Tonlage. Damit leiteten sie den Gesang." },
      { number: 22, text: "Kenanja war der Verantwortliche der Leviten für Tragearbeiten. Weil er sich darauf verstand, gab er auch die Anweisungen für den Transport der Bundeslade." },
      { number: 23, text: "Berechja und Elkana gingen als Wächter voraus." },
      { number: 24, text: "Vor der Lade gingen die Priester Schebanja, Joschafat, Netanel, Amasai, Secharja, Benanja und Eliëser und bliesen auf ihren Trompeten, und hinter ihr folgten Obed-Edom und Jehija als Wächter." },
      { number: 25, text: "So zog David mit den Ältesten von Israel und den Anführern der Heereseinheiten freudig aus, um die Bundeslade Jahwes aus dem Haus Obed-Edoms abzuholen." },
      { number: 26, text: "Weil Gott es den Leviten, die die Bundeslade Jahwes trugen, gelingen ließ, opferte man sieben Stiere und sieben Schafböcke." },
      { number: 27, text: "David trug ein Obergewand aus feinem weißen Leinen, ebenso wie die Leviten, die die Lade trugen, die Sänger und Kenanja, der den Transport beaufsichtigte. David trug außerdem ein leinenes Efod*.", footnotes: ["Das Efod aus Leinen war offenbar ein ärmelloses Gewand und gehörte zur Dienstkleidung eines Priesters, muss aber von dem Efod des Hohen Priesters (2. Mose 39) unterschieden werden, das aus anderem Material hergestellt wurde."] },
      { number: 28, text: "So brachte ganz Israel die Bundeslade Jahwes jubelnd und mit Hörnerschall unter dem Klang von Trompeten und Zimbeln, Harfen und Zithern hinauf." },
      { number: 29, text: "Als die Bundeslade Jahwes in die Stadt getragen wurde, schaute Michal, die Tochter Sauls, aus dem Fenster. Und als sie sah, wie König David hüpfte und tanzte, verachtete sie ihn innerlich." },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Man brachte die Lade Gottes in das Zelt, das David für sie errichtet hatte. Dann wurden Brand- und Freudenopfer* vor Gott geschlachtet.", footnotes: ["Beim Freudenopfer wurde im Gegensatz zum Brandopfer, bei dem das ganze Tier verbrannt wurde, nur das Fett auf dem Altar verbrannt. Der größte Teil des Tieres durfte bei einer fröhlichen Opfermahlzeit gemeinsam mit Verwandten und Freunden verzehrt werden."] },
      { number: 2, text: "Nach dem Opfermahl segnete David das Volk im Namen Jahwes." },
      { number: 3, text: "Dann ließ er an jeden Israeliten, Mann und Frau, je einen Brotfladen, eine Portion Dattelkuchen und eine Portion Rosinenkuchen verteilen." },
      { number: 4, text: "Einige Leviten setzte er zum Dienst vor der Lade Jahwes ein, um Jahwe, den Gott Israels, auch weiterhin zu rühmen, zu preisen und zu loben." },
      { number: 5, text: "Als Oberhaupt bestimmte er Asaf, als seinen Stellvertreter Secharja, dann Jaasiël, Schemiramot, Jehiël, Mattitja, Eliab, Benaja, Obed-Edom und Jëiël. Sie sollten sich mit Harfen und Zithern hören lassen, Asaf auf der Zimbel," },
      { number: 6, text: "und die Priester Benaja und Jahasiël ständig mit Trompeten vor der Bundeslade Gottes." },
      { number: 7, text: "Damals, an jenem Tag, beauftragte David Asaf und seine Brüder zum ersten Mal, Jahwe so zu loben:*", heading: "Davids Danklied", footnotes: ["Verse 8-22: Siehe Psalm 105,1-15! Verse 23-33: Siehe Psalm 96!"] },
      { number: 8, text: "Preist Jahwe! Ruft aus seinen Namen, / macht den Völkern seine Taten bekannt!" },
      { number: 9, text: "Singt ihm, spielt ihm / und redet von all seinen Wundern!" },
      { number: 10, text: "Rühmt euch seines heiligen Namens! / Die ihn suchen, können sich freuen!" },
      { number: 11, text: "Fragt nach Jahwe und seiner Macht, / sucht seine Nähe zu aller Zeit!" },
      { number: 12, text: "Denkt an die Wunder, die er tat, / die Beweise seiner Macht und seine Rechtsentscheide." },
      { number: 13, text: "Ihr Nachkommen seines Dieners Israel, / ihr Söhne Jakobs, seine Erwählten:" },
      { number: 14, text: "Das ist Jahwe, unser Gott! / Seine Rechtsentscheide gelten in der ganzen Welt." },
      { number: 15, text: "Denkt immer wieder an seinen Bund / – sein Versprechen gilt tausend Generationen –," },
      { number: 16, text: "den er mit Abraham schloss, / und an seinen Eid mit Isaak!" },
      { number: 17, text: "Er gab ihn Jakob als Ordnung, / Israel als ewigen Bund." },
      { number: 18, text: "Er sagte: Dir will ich das Land Kanaan geben, / als Erbland, das euch zugeteilt ist." },
      { number: 19, text: "Ihr wart damals leicht zu zählen, / nur wenig Leute und Fremde dabei." },
      { number: 20, text: "Sie zogen von einem Volk zum anderen, / von einem Reich zu einem anderen Volk." },
      { number: 21, text: "Er erlaubte keinem Menschen, sie zu bedrücken, / ihretwegen wies er Könige zurecht:" },
      { number: 22, text: "\"Tastet meine Gesalbten nicht an, / tut meinen Propheten nichts Böses!\"" },
      { number: 23, text: "Singe Jahwe, ganze Erde! / Verkündet seine Rettung jeden Tag!" },
      { number: 24, text: "Erzählt bei den Völkern von seiner Herrlichkeit, / von seinen Wundern bei allen Nationen!" },
      { number: 25, text: "Denn Jahwe ist groß und sehr zu loben, / mehr zu fürchten als alle Götter." },
      { number: 26, text: "Denn alle Götter der Völker sind Nichtse, / doch Jahwe hat den Himmel gemacht." },
      { number: 27, text: "Macht und Hoheit strahlt er aus, / Pracht und Herrlichkeit in seinem Heiligtum." },
      { number: 28, text: "Gebt Jahwe, ihr Völkerstämme, / gebt Jahwe Ehre und Macht!" },
      { number: 29, text: "Gebt ihm seines Namens Herrlichkeit! / Bringt ihm seine Gaben, kommt zu ihm! / Huldigt Jahwe in heiliger Pracht!" },
      { number: 30, text: "Die ganze Welt erzittere vor ihm! / Doch die Erde steht fest und wankt nicht." },
      { number: 31, text: "Der Himmel freue sich, es jauchze die Erde! / Man sage den Völkern: \"Jahwe ist König!\"" },
      { number: 32, text: "Es tose das Meer und was es erfüllt! / Es jauchze das Feld und alles darauf!" },
      { number: 33, text: "Auch die Bäume im Wald sollen jubeln vor Jahwe. / Denn er kommt, um die Erde zu richten." },
      { number: 34, text: "Preist Jahwe! Denn er ist gut / und seine Gnade hört niemals auf." },
      { number: 35, text: "Sagt: \"Rette uns, Gott unserer Rettung, / sammle uns und befreie uns aus den Nationen, / dass dein heiliger Name gepriesen wird / und wir uns deines Lobes rühmen!\"" },
      { number: 36, text: "Gelobt sei Jahwe, der Gott Israels, / in alle Zeit und Ewigkeit! / Das ganze Volk sagte: Amen*! und lobte Jahwe.", footnotes: ["Amen. Hebräisch: Es werde wahr! Oder: So sei es!"] },
      { number: 37, text: "David ließ Asaf und die Männer seiner Sippe ständig vor der Bundeslade Jahwes bleiben, um dort den täglich notwendigen Dienst zu tun.", heading: "Die Aufgaben der Leviten" },
      { number: 38, text: "Obed-Edom, den Sohn Jedutuns, und die 68 Männer seiner Sippe ließ er ebenso wie Hosea ihren Dienst als Torwächter aufnehmen." },
      { number: 39, text: "Den Priester Zadok und die anderen Priester ließ David bei der Wohnung Jahwes ihren Dienst verrichten, die auf der Höhe bei Gibeon* steht.", footnotes: ["Wohnung Jahwes ... bei Gibeon.Das Zelt der Gottesbegegnung hatte normalerweise seinen Platz in Schilo (Josua 18,1). Nach der Zerstörung Schilos durch die Philister (Jeremia 7,12-14) wurde sie mit dem Altar nach Gibeon gebracht."] },
      { number: 40, text: "Sie sollten Jahwe jeden Morgen und Abend die Brandopfer bringen und alles tun, was im Gesetz Jahwes für die Israeliten vorgeschrieben ist." },
      { number: 41, text: "Bei ihnen waren Heman und Jedutun und die, die namentlich dazu bestimmt worden waren, Jahwe für seine ewige Gnade zu preisen." },
      { number: 42, text: "Heman und Jedutun hatten Trompeten und Zimbeln und die anderen Musikinstrumente für das Lob Gottes dabei. Torwächter in Gibeon waren die Söhne Jedutuns." },
      { number: 43, text: "Dann kehrten alle Israeliten wieder nach Hause zurück. Auch David ging, um seiner Familie den Segensgruß zu bringen." },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Als nun David in seinem Palast wohnte, sagte er eines Tages zum Propheten Natan: \"Sieh doch, ich wohne hier in einem Palast aus Zedernholz, und die Bundeslade Jahwes steht nur in einem Zelt.\"", heading: "Die Bundeszusage (17)\nGottes Verheißung für David" },
      { number: 2, text: "Natan sagte: \"Tu, was du auf dem Herzen hast, denn Gott ist mit dir!\"" },
      { number: 3, text: "Aber in der folgenden Nacht kam ein Wort Gottes zu Natan:" },
      { number: 4, text: "\"Geh zu meinem Diener David und richte ihm aus: 'So spricht Jahwe: Nicht du wirst mir das Haus zur Wohnung bauen." },
      { number: 5, text: "Seit ich Israel aus Ägypten herausführte, habe ich noch nie in einem Haus gewohnt, sondern bin bis heute in einer Zeltwohnung umhergezogen." },
      { number: 6, text: "Habe ich während dieser ganzen Zeit jemals zu einem der Führer Israels, denen ich aufgetragen hatte, mein Volk Israel zu weiden, gesagt: 'Warum baut ihr mir kein Haus aus Zedernholz?'" },
      { number: 7, text: "Darum sollst du meinem Diener David ausrichten: 'So spricht Jahwe, der Allmächtige: Ich selbst habe dich von der Schafherde weggeholt und dich zum Herrscher über mein Volk Israel gemacht." },
      { number: 8, text: "Und wohin du auch gegangen bist, bin ich bei dir gewesen und habe alle deine Feinde vor dir beseitigt. Ich habe deinen Namen berühmt gemacht. Du wirst zu den Großen der Erde gezählt." },
      { number: 9, text: "Ich habe meinem Volk Israel eine Heimat gegeben, ein Land, in dem es sicher leben kann und nicht mehr zittern muss. Böse Menschen werden es nicht mehr unterdrücken wie früher" },
      { number: 10, text: "und auch noch zu der Zeit, als ich Richter über mein Volk Israel einsetzte. Ich habe alle deine Feinde gedemütigt. Und nun kündigt Jahwe dir an, dass er dein Königsgeschlecht bestehen lassen wird." },
      { number: 11, text: "Wenn deine Zeit abgelaufen ist und du gestorben bist, werde ich dir einen deiner eigenen Nachkommen auf dem Thron folgen lassen und seine Herrschaft festigen." },
      { number: 12, text: "Der wird dann ein Haus für meinen Namen bauen. Und seinem Königtum werde ich ewigen Bestand geben." },
      { number: 13, text: "Ich werde sein Vater sein und er soll mir Sohn sein. Meine Gnade entziehe ich ihm nicht, wie ich sie deinem Vorgänger entzog." },
      { number: 14, text: "Ich werde ihn für immer bestehen lassen in meinem Haus und meinem Königtum, und sein Thron soll allezeit fest stehen.'\"" },
      { number: 15, text: "Natan gab David alles genauso weiter, wie es ihm gesagt und offenbart worden war." },
      { number: 16, text: "Da ging David in das Zelt, setzte sich vor Jahwe nieder und sagte: \"Wer bin ich schon, Jahwe, mein Gott, und was bedeutet meine Familie, dass du mich bis hierher gebracht hast?", heading: "Davids Dankgebet" },
      { number: 17, text: "Und das war dir noch zu wenig, mein Gott! Du hast sogar Zusagen gemacht, die noch meinen fernen Nachkommen gelten. Und mich siehst du als Menschen von hohem Rang an, Herr, mein Gott." },
      { number: 18, text: "Was soll David da noch weiter sagen von der Ehre, die du deinem Diener erweist? Du kennst ja deinen Diener." },
      { number: 19, text: "Weil du mich liebst, Jahwe, und weil es dein Wille war, hast du all das Große getan, um es deinen Diener erkennen zu lassen." },
      { number: 20, text: "Niemand ist dir gleich, Jahwe. Nach allem, was wir gehört haben, gibt es keinen Gott außer dir." },
      { number: 21, text: "Und welches Volk gleicht deinem Volk Israel? Es ist die einzige Nation auf der Erde, die Gott aus der Sklaverei befreit und zu seinem Volk gemacht hat. So hast du dir mit großen und furchterregenden Dingen einen Namen gemacht. Aus Ägypten hast du es befreit und hast andere Völker vor ihm vertrieben." },
      { number: 22, text: "Für alle Zeiten hast du dir Israel zu deinem Volk gemacht, und du selbst, Jahwe, bist sein Gott geworden." },
      { number: 23, text: "Und nun, Jahwe, lass die Zusage, die du deinem Diener und seinem Königshaus gemacht hast, für immer gültig sein, und tu, was du versprochen hast!" },
      { number: 24, text: "Dann wird dein Name als zuverlässig gelten und groß für alle Zeiten sein, und man wird sagen: 'Jahwe, der Allmächtige, Israels Gott, ist Gott über Israel!' Und auch das Königshaus deines Dieners David wird vor dir gesichert sein." },
      { number: 25, text: "Denn du, Jahwe, mein Gott, du hast deinem Diener enthüllt: 'Ich werde dein Königsgeschlecht bestehen lassen!' Darum hat dein Diener es gewagt, so zu dir zu beten." },
      { number: 26, text: "Und nun, Jahwe, du allein bist wirklich Gott, und du hast deinem Diener all das Gute versprochen." },
      { number: 27, text: "Und nun hat es dir gefallen, das Königshaus deines Dieners zu segnen, dass es für immer vor dir bestehe! Denn du, Jahwe, du hast es gesegnet, es wird für immer gesegnet sein!\"" },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Einige Zeit später besiegte David die Philister. Er unterwarf sie und nahm ihnen die Stadt Gat und ihre umliegenden Ortschaften aus der Hand.", heading: "Vernichtung der äußeren Feinde (18-20)\nDavids Kriege und Siege" },
      { number: 2, text: "Er unterwarf auch die Moabiter* und machte sie tributpflichtig.", footnotes: ["Die Moabiter lebten östlich vom Toten Meer zwischen den Flüssen Arnon und Zered."] },
      { number: 3, text: "Ebenso besiegte David König Hadad-Eser von Zoba* bei Hamat, der gerade ausgezogen war, um seine Macht am oberen Euphrat wiederherzustellen.", footnotes: ["Zoba war ein kleines Königreich nördlich von Damaskus."] },
      { number: 4, text: "David nahm 1000 Wagen, 7000 Reiter und 20.000 Fußsoldaten von ihm gefangen. Alle Streitwagen ließ er unbrauchbar machen, nur 100 behielt er für sich." },
      { number: 5, text: "Als die Syrer von Damaskus König Hadad-Eser von Zoba zu Hilfe kamen, besiegte David auch sie und tötete 22.000 Mann." },
      { number: 6, text: "David legte Besatzungen in das damaszenische Syrien. So wurden die Syrer David untertan und mussten ihm regelmäßig Tribut zahlen. Jahwe half David überall, wohin er zog." },
      { number: 7, text: "David erbeutete die goldenen Schilde, die Hadad-Esers Offiziere getragen hatten, und brachte sie nach Jerusalem." },
      { number: 8, text: "Aus den Städten Tibhat und Kun, die zu Hadad-Esers Gebiet gehörten, nahm er eine große Menge Bronze mit. Daraus ließ Salomo später das \"bronzene Meer\", die Säulen und die Gegenstände aus Bronze* gießen.", footnotes: ["Gegenstände aus Bronze.Alles war für den späteren Tempel bestimmt."] },
      { number: 9, text: "Als König Toï von Hamat hörte, dass David die ganze Streitmacht des Königs Hadad-Eser von Zoba vernichtet hatte," },
      { number: 10, text: "schickte er seinen Sohn Joram zu ihm. Er sollte König David Grüße ausrichten und ihn zu seinem Sieg über Hadad-Eser beglückwünschen. Hadad-Eser hatte nämlich ständig gegen Toï Krieg geführt. Joram brachte Geräte aus Gold, Silber und Bronze mit." },
      { number: 11, text: "Auch diese weihte König David Jahwe, ebenso wie das Silber und Gold, das er von den Völkern bekam, die er unterworfen hatte: von den Edomitern, den Moabitern und Ammonitern*, von den Philistern und den Amalekitern.", footnotes: ["Die Ammoniter waren nordöstliche Nachbarn der Moabiter."] },
      { number: 12, text: "Abischai Ben-Zeruja besiegte die Edomiter im Salztal. 18.000 Mann erschlug er dort." },
      { number: 13, text: "Im ganzen Land Edom setzte David dann Statthalter ein und machte die Edomiter zu seinen Untertanen. So half Jahwe David überall, wohin er zog." },
      { number: 14, text: "David regierte als König über ganz Israel und sorgte für Recht und Gerechtigkeit in seinem Volk." },
      { number: 15, text: "Joab Ben-Zeruja war Oberbefehlshaber über das Heer. Joschafat Ben-Ahilud war Kanzler.", heading: "Davids Beamte" },
      { number: 16, text: "Zadok Ben-Ahitub und Ahimelech Ben-Abjatar waren Priester, Schawscha war Staatsschreiber." },
      { number: 17, text: "Benaja Ben-Jojada befehligte die Leibgarde*. Die Söhne Davids nahmen führende Stellungen im königlichen Dienst ein.", footnotes: ["Leibgarde. Wörtlich: Die Kreter und Pleter. Vielleicht sind damit Männer von zwei aus Kreta stammenden Philisterstämmen gemeint, die David als Leibwächter in der königlichen Leibgarde dienten."] },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Einige Zeit später starb König Nahasch von Ammon, und sein Sohn trat die Nachfolge an.", heading: "Krieg gegen die Ammoniter" },
      { number: 2, text: "David dachte: \"Ich will Hanun Ben-Nahasch Freundlichkeit erweisen, wie sein Vater auch mir gegenüber Freundlichkeit gezeigt hat.\" So schickte er eine Gesandtschaft, um ihm sein Beileid auszusprechen. Als die Gesandten Davids im Ammoniterland ankamen," },
      { number: 3, text: "sagten die Oberen der Ammoniter zu Hanun: \"Denkst du wirklich, dass David deinen Vater ehren will, wenn er dir sein Beileid ausspricht? Er hat die Gesandten doch nur geschickt, um das Land zu erkunden. Er will es auskundschaften, um es später zerstören zu können.\"" },
      { number: 4, text: "Da ließ Hanun die Gesandten Davids ergreifen, ließ sie scheren und ihnen die Gewänder unten bis zum Gesäß abschneiden und schickte sie weg." },
      { number: 5, text: "Als man David berichtete, wie schwer seine Männer beschämt worden waren, schickte er ihnen Boten entgegen und ließ ihnen sagen: \"Bleibt in Jericho, bis euer Bart wieder gewachsen ist, und kommt dann zurück.\"" },
      { number: 6, text: "Als König Hanun und die Ammoniter merkten, dass sie sich bei David verhasst gemacht hatten, schickten sie Unterhändler mit 35.000 Kilogramm Silber nach Mesopotamien, nach Maacha in Syrien und nach Zoba, um Streitwagen und Wagenkämpfer anzuwerben." },
      { number: 7, text: "Sie machten sich 32.000 Wagenkämpfer dienstbar und gewannen den König von Maacha mit seinem Volk dazu. Sie alle kamen und schlugen ihr Lager bei Medeba auf." },
      { number: 8, text: "Als David davon hörte, ließ er Joab mit dem ganzen Heer und der Elitetruppe ausrücken." },
      { number: 9, text: "Die Ammoniter bezogen Stellung vor dem Tor ihrer Stadt. Aber die Könige, die gekommen waren, stellten sich in einiger Entfernung auf offenem Feld zur Schlacht auf." },
      { number: 10, text: "Als Joab sah, dass er eine Front vor sich und eine im Rücken hatte, wählte er seine besten Leute aus und stellte sich mit ihnen den Syrern entgegen." },
      { number: 11, text: "Die übrigen sollten sich unter dem Kommando seines Bruders Abischai den Ammonitern entgegenstellen." },
      { number: 12, text: "Joab sagte: \"Wenn die Syrer stärker sind als ich, kommst du mir zu Hilfe. Und wenn dir die Ammoniter zu stark werden, helfe ich dir." },
      { number: 13, text: "Hab Mut und lass uns stark sein für unser Volk und die Städte unseres Gottes! Dann soll Jahwe tun, was ihm gefällt.\"" },
      { number: 14, text: "Joab rückte mit seiner Truppe zur Schlacht gegen die Syrer vor. Da flohen sie vor ihm." },
      { number: 15, text: "Als die Ammoniter sahen, dass die Syrer flohen, ergriffen auch sie vor Abischai die Flucht und zogen sich in die Stadt zurück. Da kehrte Joab wieder nach Jerusalem heim." },
      { number: 16, text: "Als die Syrer erkannten, dass sie von Israel besiegt worden waren, ließen sie auch die syrischen Truppen von jenseits des Euphrat zu Hilfe kommen. Unter dem Befehl Schobachs, des Heerführers von Hadad-Eser, rückten sie an." },
      { number: 17, text: "Als David das gemeldet wurde, rief er alle wehrfähigen Männer Israels zusammen, überquerte mit ihnen den Jordan und stellte sich den Syrern zur Schlacht. Als es zum Kampf kam," },
      { number: 18, text: "wurden die Syrer von Israel in die Flucht geschlagen. Davids Männer erschlugen 7000 syrische Wagenkämpfer* und 40.000 Mann vom Fußvolk. Auch Schobach, ihren Heerführer, töteten sie.", footnotes: ["7000 syrische Wagenkämpfer. 2. Samuel 10,18 hat nur 700, was offenbar ein Kopierfehler ist."] },
      { number: 19, text: "Als nun die Vasallen Hadad-Esers sahen, dass sie von Israel geschlagen waren, schlossen sie Frieden mit David und unterwarfen sich. Die Syrer wagten es nicht, den Ammonitern noch einmal zu helfen." },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Als der Frühling kam, begann wieder die Zeit, in der die Könige ihre Feldzüge unternahmen. Auch Joab zog mit dem ganzen Heer Israels los und verwüstete das Land der Ammoniter und belagerte Rabba*. David selbst blieb in Jerusalem. Joab eroberte Rabba und zerstörte es.", footnotes: ["Rabba war die Hauptstadt der Ammoniter und lag 38 km östlich vom Jordan, heute: Amman."] },
      { number: 2, text: "David nahm ihrem König die Krone vom Kopf und setzte sie selbst auf. Ihr Gewicht betrug 34 Kilogramm*. Sie bestand ganz aus Gold und war mit einem kostbaren Edelstein besetzt. Außerdem nahm er reiche Beute aus der Stadt mit.", footnotes: ["34 Kilogramm. Wörtlich: ein Talent. Die Krone wurde offenbar nur kurz bei besonderen Anlässen getragen."] },
      { number: 3, text: "Die Bevölkerung der Stadt ließ David Zwangsarbeiten verrichten. Er stellte sie an Steinsägen, eiserne Pickel und Beile*. So machte er es auch mit den anderen Städten der Ammoniter. Dann kehrte er mit dem ganzen Heer nach Jerusalem zurück.", footnotes: ["Beile. So mit 2. Samuel 12,31. Wörtlich: Steinsägen."] },
      { number: 4, text: "Danach kam es bei Geser zum Kampf mit den Philistern. Damals tötete Sibbechai aus Huscha den Sippai, der zu den Nachkommen des Rafa* gehörte, und die Philister wurden in die Knie gezwungen.", heading: "Davids Helden und ihre Taten", footnotes: ["Rafa gilt als Stammvater der Refaïter, das sind Riesen."] },
      { number: 5, text: "Bei einem weiteren Kampf erschlug Elhanan Ben-Jaïr den Bruder Goliats aus Gat, dessen Speer so dick wie ein Weberbaum* war.", footnotes: ["Weberbaum. So hießen die Querstangen an den beiden Enden des Webstuhls, an denen die Kettfäden befestigt wurden. Sie mussten eine beträchtliche Dicke haben."] },
      { number: 6, text: "Wieder kam es zum Kampf bei Gat. Da trat ein besonders großer Mann hervor, der an jeder Hand sechs Finger und an jedem Fuß sechs Zehen hatte, insgesamt also 24. Auch er war ein Nachkomme Rafas." },
      { number: 7, text: "Er verhöhnte Israel. Da erschlug ihn Jonatan Ben-Schima, der Neffe Davids." },
      { number: 8, text: "Sie alle waren Nachkommen von Rafa aus Gat und wurden von David und seinen Männern erschlagen." },
    ] },
    { number: 21, verses: [
      { number: 1, text: "Der Satan stellte sich gegen Israel und verleitete David, das Volk zu zählen.*", heading: "Vorbereitung für den Tempelbau (21-29)\nDavids Volkszählung", footnotes: ["Satan ... zählen. Gott (2. Samuel 24,1) prüfte David, um ihm eine Lehre zu erteilen und benutzte dazu den Satan, der Israel schaden wollte."] },
      { number: 2, text: "David sagte zu Joab und den Oberen des Volkes: \"Geht durch das ganze Land von Beerscheba bis Dan und zählt die Israeliten. Sagt mir das Ergebnis, ich will wissen, wie viele es sind.\"" },
      { number: 3, text: "Doch Joab sagte: \"Möge Jahwe das Volk noch hundertmal zahlreicher machen, als es schon ist! Und sind sie nicht alle deine treuen Diener, mein Herr und König? Warum nur willst du so etwas tun? Warum soll Israel schuldig werden?\"" },
      { number: 4, text: "Doch der König bestand vor Joab auf seinem Befehl. So machte sich dieser auf den Weg. Er durchzog ganz Israel und kam dann nach Jerusalem zurück." },
      { number: 5, text: "Joab teilte dem König das Ergebnis der Zählung mit: die Gesamtzahl der Männer, die mit dem Schwert umgehen konnten, betrug in ganz Israel 1.100.000 und in Juda 470.000." },
      { number: 6, text: "Die Stämme Levi und Benjamin hatte er nicht gezählt, denn der Befehl des Königs war Joab ein Gräuel." },
      { number: 7, text: "Auch Gott missfiel diese Sache und er bestrafte Israel." },
      { number: 8, text: "Da sagte David zu Gott: \"Ich habe mich schwer versündigt mit dem, was ich getan habe. Vergib doch bitte die Schuld deines Dieners. Ich habe sehr unbesonnen gehandelt.\"" },
      { number: 9, text: "Da sagte Gott zu Gad, dem Seher Davids:" },
      { number: 10, text: "\"Geh zu David und richte ihm aus: 'So spricht Jahwe: Dreierlei lege ich dir vor. Wähl dir aus, was ich dir antun soll!'\"" },
      { number: 11, text: "Gad kam zu David und sagte: \"So spricht Jahwe:" },
      { number: 12, text: "'Soll eine dreijährige Hungersnot kommen? Oder willst du drei Monate vor deinen Verfolgern fliehen und zugrunde gerichtet werden, wenn das Schwert dich einholt? Oder soll drei Tage lang das Schwert Jahwes, die Pest, im Land wüten, dass der Engel Jahwes im ganzen Gebiet Israels Verderben bringt?' Nun sag mir, welche Antwort ich dem überbringen soll, der mich gesandt hat.\"" },
      { number: 13, text: "David sagte zu Gad: \"Ich habe große Angst. Dann will ich lieber in die Hand Jahwes fallen, denn sein Erbarmen ist groß. In die Hand von Menschen will ich nicht geraten.\"" },
      { number: 14, text: "Da ließ Jahwe die Pest in Israel ausbrechen. 70.000 Mann starben in Israel." },
      { number: 15, text: "Gott schickte den Engel auch nach Jerusalem, um die Stadt zu vernichten. Als dieser im Begriff stand, dort sein Vernichtungswerk zu tun, hatte Jahwe Mitleid. Er sagte dem Todesengel: \"Genug! Hör auf damit!\"Der Engel Jahwes stand gerade am Dreschplatz von Arauna, einem Jebusiter." },
      { number: 16, text: "Als David aufblickte, sah er den Engel Jahwes zwischen Erde und Himmel stehen, das Schwert gezückt und über Jerusalem ausgestreckt. David und die Ältesten der Stadt hatten den Trauersack angezogen. Sie warfen sich nieder mit dem Gesicht zur Erde." },
      { number: 17, text: "David sagte zu Gott: \"Ich habe doch befohlen, das Volk zu zählen, ich habe doch gesündigt, ich habe doch das Böse getan. Was haben denn diese Schafe getan? Jahwe, mein Gott, bestrafe doch mich und meine Familie, aber verschone dein Volk mit dieser Plage!\"" },
      { number: 18, text: "Der Engel Jahwes hatte Gad befohlen, David zu sagen, er solle zum Dreschplatz des Jebusiters Arauna* hinaufgehen und dort einen Altar errichten.", heading: "David baut einen Altar auf dem Dreschplatz", footnotes: ["Arauna. Wörtlich: Ornan, was eine andere Form desselben Namens ist."] },
      { number: 19, text: "Da ging David hinauf, wie Gad ihm im Namen Jahwes befohlen hatte." },
      { number: 20, text: "Arauna drosch gerade Weizen aus. Als er sich umblickte, hatte er den Engel gesehen. Seine vier Söhne waren weggelaufen und hatten sich versteckt." },
      { number: 21, text: "Nun kam David zu Arauna. Als dieser aufschaute und ihn erkannte, ging er ihm vom Dreschplatz aus entgegen und warf sich vor David nieder, mit dem Gesicht auf den Boden." },
      { number: 22, text: "David sagte zu ihm: \"Gib mir den Dreschplatz, denn ich möchte Jahwe einen Altar darauf bauen. Ich will ihn dir zum vollen Preis abkaufen, damit die Plage vom Volk abgewehrt wird.\"" },
      { number: 23, text: "Arauna erwiderte: \"Nimm ihn dir! Mein Herr und König möge tun, was er für richtig hält. Hier sind die Rinder zum Brandopfer. Die Dreschschlitten können das Brennholz sein und der Weizen das Speisopfer. Ich schenke dir das alles.\"" },
      { number: 24, text: "\"Nein\", sagte der König, \"ich will es zum vollen Preis von dir kaufen. Ich will dir dein Eigentum nicht für Jahwe wegnehmen, ich will keine kostenlosen Opfer bringen.\"" },
      { number: 25, text: "David gab Arauna 600 Goldstücke für den Platz*.", footnotes: ["Platz. Offenbar hat David den Platz des ganzen späteren Tempelareals gekauft, nicht nur den Dreschplatz. Das erklärt auch den Preisunterschied zu 2. Samuel 24,24."] },
      { number: 26, text: "Dort baute David Jahwe einen Altar und opferte Brand- und Freudenopfer. Dabei rief er zu Jahwe. Und Jahwe antwortete ihm mit Feuer, das vom Himmel auf den Brandopferaltar fiel." },
      { number: 27, text: "Jahwe befahl dem Engel, das Schwert wieder einzustecken, und der steckte es in die Scheide." },
      { number: 28, text: "Damals erkannte David, dass Jahwe ihn erhört hatte und dass er ihm auf dem Dreschplatz des Jebusiters Arauna opfern durfte." },
      { number: 29, text: "Die Wohnung Jahwes, die Mose in der Wüste angefertigt hatte, und der Brandopferaltar befanden sich zu dieser Zeit noch auf der Anhöhe bei Gibeon." },
      { number: 30, text: "David wagte es nicht mehr, dorthin zu gehen, um Gott zu befragen, so sehr hatte ihn die Angst vor dem Schwert des Engels Jahwes gepackt." },
      { number: 22, text: "Deshalb sagte David: \"Hier soll das Haus Gottes, das Haus Jahwes, stehen und der Brandopferaltar für Israel.\"" },
    ] },
    { number: 22, verses: [
      { number: 2, text: "David ließ die Fremden aus dem ganzen Land zusammenholen und setzte sie als Steinhauer ein. Sie mussten die Quadersteine behauen, die für den Bau des Hauses Gottes bestimmt waren.", heading: "Vorbereitungen für den Tempelbau" },
      { number: 3, text: "David ließ eine Menge Eisen heranschaffen für die Nägel an den Torflügeln und die Klammern und soviel Bronze, dass es nicht zu wiegen war," },
      { number: 4, text: "dazu ungezählte Zedernstämme. Denn die Tyrer und Sidonier* brachten große Mengen an Zedernholz zu David.", footnotes: ["Tyrer und Sidonier nannte man die Bewohner Phöniziens (heute: Libanon) nach den beiden größten Hafenstädte Tyrus und Sidon."] },
      { number: 5, text: "David sagte: \"Mein Sohn Salomo ist noch jung und schwach. Aber das Haus, das für Jahwe gebaut werden soll, muss überaus groß werden zum Ruhm und zum Preis in allen Ländern. So will ich denn alles für ihn bereitstellen.\" Auf diese Weise traf David vor seinem Tod viele Vorbereitungen für den Bau." },
      { number: 6, text: "Dann rief er seinen Sohn Salomo und trug ihm auf, Jahwe, dem Gott Israels, ein Haus zu bauen." },
      { number: 7, text: "Er sagte: \"Mein Sohn, es lag mir am Herzen, dem Namen Jahwes, meines Gottes, ein Haus zu bauen." },
      { number: 8, text: "Aber das Wort Jahwes kam zu mir: 'Du hast viel Blut vergossen und große Kriege geführt. Du wirst kein Haus für meinen Namen bauen, denn du hast zuviel Blut vor mir auf die Erde fließen lassen." },
      { number: 9, text: "Doch du wirst einen Sohn haben, der ein Mann der Ruhe sein wird. Ihm werde ich Ruhe vor all seinen Feinden ringsum verschaffen. Er wird Salomo, der Friedliche, heißen. Und ich werde Israel Frieden und Ruhe geben, so lange er lebt." },
      { number: 10, text: "Er soll ein Haus für mich bauen. Er wird ein Sohn für mich sein und ich ein Vater für ihn. Seiner Herrschaft über Israel werde ich für immer Bestand geben.'" },
      { number: 11, text: "Nun, mein Sohn, Jahwe möge mit dir sein, dass es dir nach seiner Zusage gelingt, das Haus für Jahwe, deinen Gott, zu bauen." },
      { number: 12, text: "Jahwe gebe dir Einsicht und Verstand, dass du die Weisung von Jahwe, deinem Gott, beachtest, und er setze dich zum Herrscher über Israel ein." },
      { number: 13, text: "Wenn du die Ordnungen und Rechtsbestimmungen genau befolgst, die Jahwe Mose für Israel gegeben hat, wird es dir gelingen. Sei stark und mutig, fürchte dich nicht und hab keine Angst!" },
      { number: 14, text: "Und sieh, trotz meiner Mühsal habe ich für das Haus Jahwes 3500 Tonnen Gold und 35.000 Tonnen Silber* bereitgestellt, dazu solche Mengen an Bronze und Eisen, dass man sie nicht wiegen kann. Auch Holz und Steine habe ich bereitgestellt, und du wirst noch mehr hinzufügen.", footnotes: ["3500 ... Silber. Wörtlich: 100.000 Talente Gold und 1 Million Talente Silber."] },
      { number: 15, text: "Handwerker stehen dir reichlich zur Verfügung: Steinmetze, Bauleute, Zimmerleute, dazu jede Menge Kunsthandwerker," },
      { number: 16, text: "die Arbeiten in Gold, Silber, Bronze und Eisen ausführen können. Geh also ans Werk! Jahwe wird mit dir sein!\"" },
      { number: 17, text: "David befahl auch allen Oberen in Israel, seinem Sohn Salomo beizustehen." },
      { number: 18, text: "Er sagte: \"Ist Jahwe, euer Gott, nicht bei euch? Hat er euch nicht Ruhe ringsum verschafft? Er hat ja die Bewohner des Landes in meine Hand gegeben, und das Land ist nun Jahwe und seinem Volk unterworfen." },
      { number: 19, text: "Richtet Herz und Sinn darauf, Jahwe, euren Gott, zu suchen! Und macht euch auf, das Heiligtum Gottes zu bauen, dass die Lade des Bundes mit Jahwe und die heiligen Gegenstände Gottes in das Haus kommen, das dem Namen Jahwes gebaut werden soll.\"" },
      { number: 23, text: "Als David alt war und lebenssatt, setzte er seinen Sohn Salomo zum König über Israel ein." },
    ] },
    { number: 23, verses: [
      { number: 2, text: "Er ließ dazu alle führenden Männer Israels, die Priester und die Leviten zusammenrufen.", heading: "Die Einteilung der Leviten" },
      { number: 3, text: "Alle Leviten von dreißig Jahren an aufwärts wurden gezählt. Es waren 38.000 Männer." },
      { number: 4, text: "Von diesen bestimmte David 24.000 zur Aufsicht für die Arbeit am Haus Jahwes, 6000 sollten Schriftführer und Richter sein." },
      { number: 5, text: "4000 Torwächter und 4000, die Jahwe mit den Instrumenten preisen und loben sollten, die er selbst zum Lobgesang hatte anfertigen lassen." },
      { number: 6, text: "David teilte die Leviten nach ihrer Abstammung von Gerschon, Kehat und Merari in Abteilungen ein." },
      { number: 7, text: "Zu den Gerschoniten gehörten Ladan und Schimi." },
      { number: 8, text: "Ladan hatte drei Söhne. Das Oberhaupt war Jehiël, ihm folgten Setam und Joël." },
      { number: 9, text: "Schimi hatte drei Söhne: Schelomit, Hasiël und Haran. Sie alle waren die Oberhäupter der Sippen, die von Ladan abstammten." },
      { number: 10, text: "Schimi hatte vier Söhne: Jahat, Sisa, Jëusch und Beria." },
      { number: 11, text: "Das Oberhaupt war Jahat, an zweiter Stelle stand Sisa. Jëusch und Beria hatten nur wenige Söhne und bildeten deshalb eine einzige Sippe und auch nur eine Dienstgruppe." },
      { number: 12, text: "Kehat hatte vier Söhne: Amram, Jizhar, Hebron und Usiël." },
      { number: 13, text: "Die Söhne Amrams waren Mose und Aaron. Aaron und seine Söhne wurden für immer dazu bestimmt, das Höchstheilige zu heiligen, Rauchopfer vor Jahwe zu verbrennen, ihm zu dienen und allezeit in seinem Namen zu segnen." },
      { number: 14, text: "Die Nachkommen des Gottesmannes Mose wurden den Leviten zugerechnet." },
      { number: 15, text: "Die Söhne Moses waren Gerschom und Eliëser." },
      { number: 16, text: "Von den Söhnen Gerschoms war Schubaël das Oberhaupt." },
      { number: 17, text: "Von den Söhnen Eliësers war sein einziger Sohn Rehabja das Oberhaupt. Dieser hatte aber sehr viele Söhne." },
      { number: 18, text: "Von den Söhnen Jizhars war Schelomit das Oberhaupt." },
      { number: 19, text: "Von den Söhnen Hebrons war Jerija das Oberhaupt, Amarja der zweite, Jahasiël der dritte und Jekamam der vierte." },
      { number: 20, text: "Von den Söhnen Usiëls war Micha das Oberhaupt und Jischija der zweite." },
      { number: 21, text: "Die Söhne Meraris waren Machli und Muschi, die Söhne Machlis: Eleasar und Kisch." },
      { number: 22, text: "Als Eleasar starb, hinterließ er keine Söhne, sondern nur Töchter. Sie wurden aber von den Söhnen ihres Onkels Kisch geheiratet." },
      { number: 23, text: "Muschi hatte drei Söhne: Machli, Eder und Jeremot." },
      { number: 24, text: "Das waren die Nachkommen Levis nach ihren Familien, die Oberhäupter der Familien nach ihren Dienstgruppen, wie sie Kopf für Kopf bestellt worden waren, um die Arbeit im Dienst für das Haus Jahwes zu tun, von zwanzig Jahren* an aufwärts.", heading: "Die Aufgaben der Leviten", footnotes: ["zwanzig Jahre.Siehe die Fußnote zu 4. Mose 8,24."] },
      { number: 25, text: "David sagte: \"Jahwe, der Gott Israels, hat seinem Volk Ruhe verschafft und wohnt nun für immer in Jerusalem." },
      { number: 26, text: "So müssen auch die Leviten die Wohnung mit allen Gegenständen, die für den Dienst gebraucht werden, nicht mehr tragen.\" –" },
      { number: 27, text: "Denn nach den letzten Anordnungen Davids wurden die Leviten von zwanzig Jahren an und darüber gezählt. –" },
      { number: 28, text: "\"Denn ihr Platz ist an der Seite der Nachkommen Aarons im Dienst für das Haus Jahwes. Sie sollen die Vorhöfe und Kammern in Ordnung halten, die heiligen Gegenstände reinigen und alles erledigen, was sonst noch im Haus Gottes anfällt." },
      { number: 29, text: "Sie haben für die geweihten Brote zu sorgen, für das Feinmehl zum Speisopfer, die ungesäuerten Fladenbrote, das Pfannengebäck und den Teig. Außerdem müssen sie die Hohl- und Längenmaße überwachen." },
      { number: 30, text: "Sie müssen jeden Morgen und Abend bereitstehen, um Jahwe zu preisen und zu loben," },
      { number: 31, text: "und auch immer dann, wenn Jahwe Brandopfer gebracht werden an den Sabbaten, den Neumondstagen und den Festen, ohne Ausnahme nach der für sie vorgeschriebenen Zahl." },
      { number: 32, text: "So sollen sie die Aufgaben beim Zelt der Gottesbegegnung und beim Heiligtum erfüllen und die Nachkommen Aarons bei ihren Pflichten für das Haus Jahwes unterstützen.\"" },
    ] },
    { number: 24, verses: [
      { number: 1, text: "Auch die Nachkommen Aarons wurden in Dienstgruppen eingeteilt. Aarons Söhne waren Nadab und Abihu, Eleasar und Itamar.", heading: "Die Dienstgruppen der Priester" },
      { number: 2, text: "Nadab und Abihu starben noch vor ihrem Vater und hatten selbst keine Söhne. Deshalb übten nur Eleasar und Itamar den Priesterdienst aus." },
      { number: 3, text: "Zusammen mit Zadok von den Nachkommen Eleasars und Ahimelech, einem Nachkommen Itamars, teilte David die Priester in Dienstgruppen ein." },
      { number: 4, text: "Dabei stellte sich heraus, dass die Zahl der Männer bei den Nachkommen Eleasars höher war als bei denen Itamars. Deshalb teilte man sie so ein, dass die Oberhäupter der Nachkommen Eleasars mit ihren Sippen sechzehn Dienstgruppen bildeten und die der Nachkommen Itamars acht." },
      { number: 5, text: "Die Einteilung geschah dann durch Lose, denn die Oberen des Heiligtums, die Oberen vor Gott, stammten sowohl von den Nachkommen Eleasars als auch von denen Itamars." },
      { number: 6, text: "Der Schreiber Schemaja Ben-Netanel, ein Levit, schrieb sie auf im Beisein des Königs und der Oberen, des Priesters Zadok und Ahimelech Ben-Abjatar und vor den Sippenoberhäuptern der Priester und Leviten: Abwechselnd wurden zwei Sippen von Eleasar und eine von Itamar ausgelost." },
      { number: 7, text: "Das erste Los fiel auf Jojarib, das zweite auf Jedaja," },
      { number: 8, text: "das dritte auf Harim, das vierte auf Seorim," },
      { number: 9, text: "das fünfte auf Malkija, das sechste auf Mijamin," },
      { number: 10, text: "das siebte auf Hakkoz, das achte auf Abija," },
      { number: 11, text: "das neunte auf Jeschua, das zehnte auf Schechanja," },
      { number: 12, text: "das elfte auf Eljaschib, das zwölfte auf Jakim," },
      { number: 13, text: "das 13. auf Huppa, das 14. auf Jeschebab," },
      { number: 14, text: "das 15. auf Bilga, das 16. auf Immer," },
      { number: 15, text: "das 17. auf Hesir, das 18. auf Pizez," },
      { number: 16, text: "das 19. auf Petachja, das 20. auf Jeheskel," },
      { number: 17, text: "das 21. auf Jachin, das 22. auf Gamul," },
      { number: 18, text: "das 23. auf Delaja, das 24. auf Maasja." },
      { number: 19, text: "Das waren ihre Dienstgruppen, nach denen sie zum Dienst ins Haus Jahwes kommen mussten. Es geschah nach der Vorschrift, die ihnen ihr Stammvater Aaron auf Befehl Jahwes, des Gottes Israels, gegeben hatte." },
      { number: 20, text: "Von den übrigen Leviten wurde Schubaël von den Nachkommen Amrams genannt und Jechdeja von den Söhnen Schubaëls.", heading: "Weitere Dienstgruppen der Leviten" },
      { number: 21, text: "Jischija war das Oberhaupt der Söhne Rehabjas." },
      { number: 22, text: "Dann kam Schelomit von den Nachkommen Jizhars und Jahat von den Söhnen Schelomits." },
      { number: 23, text: "Jerija war das Oberhaupt der Söhne Hebrons, Amarja der zweite, Jahasiël der dritte und Jekamam der vierte." },
      { number: 24, text: "Dann Micha von den Söhnen Usiëls, Schamir von den Söhnen Michas," },
      { number: 25, text: "Secharja von den Söhnen Jischijas, einem Bruder Michas." },
      { number: 26, text: "Die Nachkommen Meraris waren Machli und Muschi und die Söhne von Meraris Sohn Jaasija." },
      { number: 27, text: "Weitere Nachkommen Meraris über Jaasija waren Schoham, Sakkur und Ibri." },
      { number: 28, text: "Die Söhne Machlis waren Eleasar, der keine Söhne hatte," },
      { number: 29, text: "und Kisch. Der Sohn von Kisch war Jerachmeël." },
      { number: 30, text: "Die Söhne Muschis waren Machli, Eder und Jerimot. Das waren die Söhne der Leviten nach ihren Sippen." },
      { number: 31, text: "So wie ihre Brüder, die Nachkommen Aarons, warfen auch sie Lose in Gegenwart von König David, Zadok, Ahimelech und den Sippenoberhäuptern der Priester und Leviten. Dabei wurden die Familien der Sippenoberhäupter nicht anders behandelt als die ihrer jüngsten Brüder." },
    ] },
    { number: 25, verses: [
      { number: 1, text: "David sonderte nun zusammen mit den Heerobersten die Nachkommen Asafs, Hemans und Jedutuns aus, die auf Zithern, Harfen und Zimbeln weissagten*. Folgende Männer taten diesen Dienst:", heading: "Dienstgruppen der Sänger und Musiker", footnotes: ["Weissagen bedeutet normalerweise \"als Sprecher Gottes reden\", hier könnte auch die Entstehung und Wiedergabe geistlicher Musik gemeint sein (wie 1. Samuel 10,5; siehe auch 1. Samuel 19,20-24)."] },
      { number: 2, text: "Sakkur, Josef, Netanja und Asarela von den Söhnen Asafs. Sie standen unter der Leitung ihres Vaters, der nach Anleitung des Königs weissagte." },
      { number: 3, text: "Von den Söhnen Jedutuns waren es Gedalja, Zeri, Jesaja, Schimi, Haschabja und Mattitja, zusammen sechs. Sie sollten unter der Leitung ihres Vaters, der auf der Zither weissagte, Jahwe preisen und loben." },
      { number: 4, text: "Von den Söhnen Hemans waren es Bukkija, Mattanja, Usiël, Schubaël, Jerimot, Hananja, Hanani, Eliata, Giddalti, Romamti-Eser, Joschbekascha, Malloti, Hotir und Mahasiot." },
      { number: 5, text: "Diese alle waren Söhne von Heman, dem Seher des Königs, dem Gott zugesagt hatte, ihn zu einem angesehenen Mann* zu machen. Gott hatte ihm vierzehn Söhne und drei Töchter geschenkt.", footnotes: ["angesehenen Mann. Wörtlich: sein Horn zu erhöhen."] },
      { number: 6, text: "Alle Genannten spielten unter der Leitung ihrer Väter Asaf, Jedutun und Heman zum Gesang im Haus Jahwes auf Zimbeln, Harfen und Zithern. Das war nach Anweisung des Königs ihr Dienst im Haus Gottes." },
      { number: 7, text: "Zusammen mit ihren Stammesbrüdern, die im Gesang für Jahwe ausgebildet waren, zählten sie 288 Mann, alles Meister." },
      { number: 8, text: "Auch sie losten ihre Dienste aus, der Jüngste wie der Älteste, der Meister wie der Schüler." },
      { number: 9, text: "Das erste Los für Asaf fiel auf Josef, das zweite auf Gedalja. Er bildete zusammen mit seinen Brüdern und Söhnen eine Zwölfergruppe, wie es auch bei den nachstehend Genannten der Fall war*.", footnotes: ["wie es auch bei den nachstehend Genannten der Fall war. Eingefügt anstelle der ständigen Wiederholung \"Zusammen mit seinen Brüdern und Söhnen bildeten sie eine Zwölfergruppe\" in jedem der folgenden Verse."] },
      { number: 10, text: "Das dritte Los fiel auf Sakkur," },
      { number: 11, text: "das vierte auf Zeri," },
      { number: 12, text: "das fünfte auf Netanja," },
      { number: 13, text: "das sechste auf Bukkija," },
      { number: 14, text: "das siebte auf Asarela," },
      { number: 15, text: "das achte auf Jesaja," },
      { number: 16, text: "das neunte auf Mattanja," },
      { number: 17, text: "das zehnte auf Schimi," },
      { number: 18, text: "das elfte auf Usiël," },
      { number: 19, text: "das zwölfte auf Haschabja," },
      { number: 20, text: "das 13. auf Schubaël," },
      { number: 21, text: "das 14. auf Mattitja," },
      { number: 22, text: "das 15. auf Jeremot," },
      { number: 23, text: "das 16. auf Hananja," },
      { number: 24, text: "das 17. auf Joschbekascha," },
      { number: 25, text: "das 18. auf Hanani," },
      { number: 26, text: "das 19. auf Malloti," },
      { number: 27, text: "das 20. auf Eliata," },
      { number: 28, text: "das 21. auf Hotir," },
      { number: 29, text: "das 22. auf Giddalti," },
      { number: 30, text: "das 23. auf Mahasiot," },
      { number: 31, text: "das 24. auf Romamti-Eser." },
    ] },
    { number: 26, verses: [
      { number: 1, text: "Auch die Torwächter waren in Dienstgruppen aufgeteilt: Aus der Sippe Korach war es Meschelemja Ben-Kore von den Nachkommen Asafs.", heading: "Dienstgruppen der Torwächter" },
      { number: 2, text: "Meschelemjas Söhne waren Secharja, der Erstgeborene, der zweite Jediaël, der dritte Sebadja, der vierte Jatniël," },
      { number: 3, text: "der fünfte Elam, der sechste Johanan und der siebte Eljoënai." },
      { number: 4, text: "Obed-Edoms Söhne waren Schemaja, der Erstgeborene, der zweite Josabad, der dritte Joach, der vierte Sachar, der fünfte Netanel," },
      { number: 5, text: "der sechste Ammiël, der siebte Issachar und der achte Pëulletai. Denn Gott hatte ihn gesegnet." },
      { number: 6, text: "Auch seinem Sohn Schemaja wurden Söhne geboren. Sie bekamen führende Stellungen in ihrer Sippe, denn sie waren tüchtige Männer." },
      { number: 7, text: "Es waren Otni, Refaël, Obed und Elsabad sowie ihre Brüder Elihu und Semachja, zwei sehr tüchtige Männer." },
      { number: 8, text: "Diese alle waren Nachkommen Obed-Edoms. Sie, ihre Söhne und Brüder, waren insgesamt 62 tüchtige Männer, bestens geeignet für ihren Dienst." },
      { number: 9, text: "Meschelemjas Söhne und Brüder waren insgesamt 18 fähige Leute." },
      { number: 10, text: "Auch Hosa aus der Sippe Merari hatte Söhne. Ihr Oberhaupt war Schimi. Obwohl er nicht der Erstgeborene war, hatte sein Vater ihn zum Anführer der Dienstgruppe gemacht." },
      { number: 11, text: "Der zweite Hilkija, der dritte Tebalja und der vierte Secharja. Hosas Söhne und Brüder waren insgesamt dreizehn." },
      { number: 12, text: "Diesen Abteilungen der Torwächter fiel nach der Zahl der Oberhäupter unter den Männern ebenso wie ihren Brüdern die Aufgabe zu, im Haus Jahwes zu dienen." },
      { number: 13, text: "Sie losten aus, welche Familien die einzelnen Tore bewachen sollten. Dabei wurde der Jüngste ebenso wie der Älteste behandelt." },
      { number: 14, text: "Auf Meschelemja fiel das Los für den Osten und auf seinen Sohn Secharja, der als ein kluger Ratgeber bekannt war, das für den Norden." },
      { number: 15, text: "Auf Obed-Edom fiel das Los für den Süden und das für das Vorratshaus auf seine Söhne." },
      { number: 16, text: "Auf Schuppim und Hosa fiel das Los für den Westen mit dem Schallechet-Tor*, wo die Straße hinaufgeht. Eine Wache entsprach der anderen:", footnotes: ["Schallechet-Tor. Dieses Tempeltor wird nur hier erwähnt."] },
      { number: 17, text: "An der Ostseite sollten täglich sechs Leviten stehen, an der Nord- und Südseite je vier und am Vorratshaus zwei," },
      { number: 18, text: "am Parbar* an der Straße vier und am Parbar selbst zwei.", footnotes: ["Parbar. Wahrscheinlich ein Anbau an der Westseite des Tempelvorhofs."] },
      { number: 19, text: "Das waren die Abteilungen der Torwächter von den Nachkommen Korachs und Meraris." },
      { number: 20, text: "Einige andere Leviten hatten die Aufsicht über die Schätze des Gotteshauses und die geweihten Gaben.", heading: "Die Schatzmeister" },
      { number: 21, text: "Die Söhne Ladans, die Nachkommen der Gerschoniten, die zu Ladan gehörten, waren die Jehiëliten." },
      { number: 22, text: "Die Söhne Jehiëls, Setam und sein Bruder Joël, hatten die Aufsicht über die Schätze im Haus Jahwes." },
      { number: 23, text: "Von den Nachkommen Amrams, Jizhars, Hebrons und Usiëls" },
      { number: 24, text: "war Schubaël Ben-Gerschom, ein Enkel Moses, Oberaufseher über die Schätze." },
      { number: 25, text: "Gerschoms Bruder Eliëser hatte einen Sohn namens Rehabja. Die weiteren Nachkommen in direkter Linie waren Jesaja, Joram, Sichri und Schelomit." },
      { number: 26, text: "Dieser Schelomit und seine Brüder hatten die Aufsicht über alle Schätze der geheiligten Gaben, die König David und die Familienoberhäupter, die Anführer der Tausend- und Hundertschaften und die Heeroberen geweiht hatten." },
      { number: 27, text: "Sie hatten es aus ihrer Kriegsbeute zur Unterstützung für das Haus Jahwes gespendet." },
      { number: 28, text: "Auch alles, was der Seher Samuel, Saul Ben-Kisch, Abner Ben-Ner und Joab Ben-Zeruja gespendet hatten, stand unter der Obhut Schelomits und seiner Brüder." },
      { number: 29, text: "Von den Nachkommen Jizhars waren Kenanja und seine Söhne draußen im Land Israel als Schriftführer und Richter eingesetzt.", heading: "Die Verwaltungsdienste" },
      { number: 30, text: "Von den Nachkommen Hebrons hatten Haschabja und seine Brüder, 1700 tüchtige Leute, die Aufsicht über die Verwaltung Israels im Gebiet westlich des Jordan, und zwar über jede Arbeit, die für Jahwe und im Dienst des Königs getan wurde." },
      { number: 31, text: "Das Oberhaupt der Nachkommen Hebrons mit all ihren Sippen und Familien war Jerija. Im 40. Regierungsjahr Davids suchte man den ganzen Sippenverband ab und fand dabei in Jaser im Land Gilead* viele tüchtige Männer,", footnotes: ["Gilead bezeichnete das mittlere, manchmal auch das ganze Ostjordanland."] },
      { number: 32, text: "es waren 2700 Familienoberhäupter. David setzte auch sie als Aufseher für die Angelegenheiten Gottes und des Königs ein und zwar über die Rubeniten, die Gaditen und den halben Stamm Manasse." },
    ] },
    { number: 27, verses: [
      { number: 1, text: "Es folgt ein Verzeichnis der Sippenoberhäupter Israels, der Anführer der Tausend- und Hundertschaften und ihrer Schriftführer, die dem König in allen Angelegenheiten der Abteilungen dienten, die jeden Monat im Jahr antraten und abtraten. Jede Abteilung war 24.000 Mann stark.", heading: "Die Heerführer Davids" },
      { number: 2, text: "Der ersten Abteilung für den ersten Monat stand Jaschobam Ben-Sabdiël vor," },
      { number: 3, text: "ein Nachkomme von Perez. Er war der Befehlshaber über alle Offiziere seiner Abteilung." },
      { number: 4, text: "Der Abteilung des zweiten Monats stand Dodai aus Ahoach vor. Der höchste Offizier seiner Abteilung war Miklot." },
      { number: 5, text: "Der Heerführer für den dritten Monat war Benaja, der Sohn des Priesters Jojada." },
      { number: 6, text: "Er war einer der \"Dreißig Helden\". Als er ihr Anführer wurde, übernahm sein Sohn Ammisabad den Befehl über seine Abteilung." },
      { number: 7, text: "Der vierte für den vierten Monat war Asaël, der Bruder Joabs, später sein Sohn Sebadja." },
      { number: 8, text: "Der fünfte für den fünften Monat war Schamhut, ein Nachkomme Serachs," },
      { number: 9, text: "der sechste für den sechsten Monat war Ira Ben-Ikkesch aus Tekoa," },
      { number: 10, text: "der siebte für den siebten Monat war Helez aus Pelon vom Stamm Efraïm," },
      { number: 11, text: "der achte für den achten Monat war Sibbechai, ein Nachkomme Serachs, aus Huscha," },
      { number: 12, text: "der neunte für den neunten Monat war Abiëser aus Anatot, vom Stamm Benjamin," },
      { number: 13, text: "der zehnte für den zehnten Monat war Mahrai, ein Nachkomme Serachs, aus Netofa," },
      { number: 14, text: "der elfte für den elften Monat war Benaja aus Piraton vom Stamm Efraïm" },
      { number: 15, text: "und der zwölfte für den zwölften Monat war Heldai, ein Nachkomme Otniëls, aus Netofa." },
      { number: 16, text: "Die Stämme Israels wurden von folgenden Männern geführt. Ruben: Eliëser Ben-Sichri; Simeon: Schefatja Ben-Maacha;", heading: "Die Stammesoberhäupter" },
      { number: 17, text: "Levi: Haschabja Ben-Kemuël; Aaron: Zadok;" },
      { number: 18, text: "Juda: Elihu, ein Bruder Davids; Issachar: Omri Ben-Michael;" },
      { number: 19, text: "Sebulon: Jischmaja Ben-Obadja; Naftali: Jerimot Ben-Asriël;" },
      { number: 20, text: "Efraïm: Hoschea Ben-Asasja; West-Manasse: Joël Ben-Pedaja;" },
      { number: 21, text: "Ost-Manasse in Gilead: Jiddo Ben-Secharja; Benjamin: Jaasiël Ben-Abner;" },
      { number: 22, text: "Dan: Asarel Ben-Jeroham. Dies waren die Anführer der Stämme Israels." },
      { number: 23, text: "Die Zahl derer, die 20 Jahre alt und jünger waren, nahm David nicht mit auf, denn Jahwe hatte gesagt, dass er Israel zahlreich machen werde wie die Sterne am Himmel." },
      { number: 24, text: "Joab Ben-Zeruja hatte die Zählung begonnen, sie aber nicht vollendet, weil wegen dieser Sache ein Zorn über Israel kam. Deshalb stehen diese Zahlen nicht in der Chronik des Königs David." },
      { number: 25, text: "Über die Vorräte des Königs in Jerusalem hatte Asmawet Ben-Adiël die Aufsicht und über die Vorräte auf dem Land, in den Städten, Dörfern und Schutztürmen war Jonatan Ben-Usija eingesetzt.", heading: "Die Verwalter des königlichen Besitzes" },
      { number: 26, text: "Über die Landarbeiter hatte Esri Ben-Kelub die Aufsicht," },
      { number: 27, text: "über die Weinberge Schimi aus Rama und über die Weinvorräte in den Weinbergen Sabdi aus Schefam." },
      { number: 28, text: "Über die Oliven- und Maulbeerfeigenbäume, die in der Schefela* wuchsen, hatte Baal-Hanan aus Bet-Gader die Aufsicht und über die Ölvorräte Joasch.", footnotes: ["Schefela.Niedriges, sehr fruchtbares Hügelland, das sich in nordsüdlicher Richtung zwischen dem Gebirge und der Küstenebene des Mittelmeeres erstreckt."] },
      { number: 29, text: "Über die Rinder, die in der Scharon-Ebene* weideten, hatte Schitrai die Aufsicht, der auch von dort stammte, und über die Rinder in den Tälern Schafat Ben-Adlai.", footnotes: ["Die Scharon-Ebene ist ein 15 km breiter und 75 km langer sehr fruchtbarer Streifen am Mittelmeer von Lydda im Süden bis zum Berg Karmel im Norden."] },
      { number: 30, text: "Über die Kamele hatte der Ismaëlit Obil die Aufsicht, über die Eselinnen Jechdeja aus Meronot" },
      { number: 31, text: "und über die Schafherden der Hagariter Jasis. Das waren die Verwalter des königlichen Besitzes zur Zeit Davids." },
      { number: 32, text: "Davids Onkel Jonatan, ein verständiger und schriftkundiger Mann, war Ratgeber. Jehiël Ben-Hachmoni war der Erzieher der Königssöhne.", heading: "Die engsten Berater Davids" },
      { number: 33, text: "Ahitofel war ebenfalls königlicher Berater und der Arkiter Huschai war Freund des Königs." },
      { number: 34, text: "Nachfolger Ahitofels waren Jojada Ben-Benaja und Abjatar. Joab war Heerführer des Königs." },
    ] },
    { number: 28, verses: [
      { number: 1, text: "David ließ alle Oberen Israels nach Jerusalem kommen: die Anführer der Stämme und die Anführer der Abteilungen, die im Dienst des Königs standen, die Anführer der Tausend- und Hundertschaften, die Verwalter über alle Güter und Herden, die dem König und seinen Söhnen gehörten, dazu die Hofbeamten, die Elitetruppe und alle tüchtigen Krieger.", heading: "Davids Plan zum Tempelbau" },
      { number: 2, text: "Der König David stand auf und sagte: \"Hört zu, meine Brüder und mein Volk! Es liegt mir am Herzen, ein Haus der Ruhe für die Lade des Bundes mit Jahwe und den Fußschemel unseres Gottes zu bauen. Und ich habe Vorbereitungen für den Bau getroffen." },
      { number: 3, text: "Doch Gott hat zu mir gesagt: 'Nicht du wirst meinem Namen ein Haus bauen! Denn du bist ein Mann der Kriege und hast Blut vergossen.'" },
      { number: 4, text: "Jahwe, der Gott Israels, hat mich aus der ganzen Familie meines Vaters dazu erwählt, für immer König über Israel zu sein. Denn schon Juda erwählte er zum Fürsten und im Stamm Juda die Familie meines Vaters, und unter den Söhnen meines Vaters hat er an mir Gefallen gefunden und mich zum König über ganz Israel gemacht." },
      { number: 5, text: "Und von den vielen Söhnen, die Jahwe mir geschenkt hat, erwählte er meinen Sohn Salomo, der auf dem Thron der Königsherrschaft Jahwes über Israel sitzen soll." },
      { number: 6, text: "Er sagte zu mir: 'Dein Sohn Salomo soll mein Haus und meine Vorhöfe bauen! Denn ich habe ihn mir als Sohn erwählt, und ich selbst werde ihm Vater sein." },
      { number: 7, text: "Sein Königtum werde ich für alle Zeit fest machen, wenn auch er daran festhält, nach meinen Geboten und Rechtsordnungen zu handeln, wie es heute der Fall ist.'" },
      { number: 8, text: "Und nun, vor den Augen von ganz Israel, der Versammlung Jahwes und vor den Ohren unseres Gottes: Achtet auf alle Gebote Jahwes, unseres Gottes, und erforscht sie, damit ihr im Besitz dieses schönen Landes bleiben und es euren Nachkommen für alle Zeiten weitervererben könnt." },
      { number: 9, text: "Und du, mein Sohn Salomo, erkenne den Gott deines Vaters und diene ihm mit ganzem Herzen und verlangender Seele! Denn Jahwe erforscht alle Herzen und kennt unsere geheimsten Gedanken. Wenn du ihn suchst, lässt er sich von dir finden. Wenn du ihn aber verlässt, wird er dich für immer verstoßen." },
      { number: 10, text: "Sieh nun: Jahwe hat dich erwählt, ihm ein Haus als Heiligtum zu bauen. Sei stark und handle!\"" },
      { number: 11, text: "Darauf übergab David seinem Sohn Salomo den Plan für die Vorhalle und die dazugehörenden Bauten, die Schatzkammern, die oberen und die inneren Räume und den Plan für den Sühnedeckel*.", heading: "Der Plan des Tempels", footnotes: ["Sühnedeckel, der die Bundeslade bedeckte (2. Mose 25,10-22). Das hebräische Wort ist von einem Verb abgeleitet, das ursprünglich \"verdecken\", gewöhnlich aber \"sühnen, versöhnen\" bedeutet. Vergleiche Hebräer 9,5!"] },
      { number: 12, text: "Er gab ihm den Plan für alles, was in seinem Sinn war: für die Vorhöfe am Haus Jahwes und alle Räume ringsherum, für die Schatzkammern des Gotteshauses und die Schatzkammern für die geheiligten Gaben," },
      { number: 13, text: "für die Abteilungen der Priester und Leviten und für alle Dienstarbeiten im Haus Jahwes und für alle Gegenstände, die für den Dienst im Haus Jahwes gebraucht werden." },
      { number: 14, text: "Er bestimmte auch das Gewicht für alle Gegenstände aus Gold und Silber, die zum Dienst gebraucht wurden:" },
      { number: 15, text: "für die goldenen und silbernen Leuchter und ihre Lampen, je nachdem für welchen Zweck sie bestimmt waren;" },
      { number: 16, text: "für die Tische, auf denen die geweihten Brote lagen, und die silbernen Tische;" },
      { number: 17, text: "für die Gabeln, Becken und Kannen aus reinem Gold; für die goldenen und silbernen Becher;" },
      { number: 18, text: "für den Rauchopferaltar aus reinstem Gold und den Bau des Thronwagens mit den goldenen Cherubim, die mit ihren ausgebreiteten Flügeln die Bundeslade Jahwes beschirmen." },
      { number: 19, text: "\"All das\", sagte David, \"habe ich in schriftlicher Form aus der Hand Jahwes, die über mir war. Er gab mir Verständnis für alle Details in dem Plan.\"" },
      { number: 20, text: "Noch einmal sagte David zu seinem Sohn Salomo: \"Sei stark und mutig und handle! Fürchte dich nicht und hab keine Angst! Denn Gott, Jahwe, mein Gott, ist mit dir. Er wird dich nicht fallen lassen und auch nicht im Stich lassen, bis alle Arbeiten für den Dienst im Haus Jahwes vollendet sind." },
      { number: 21, text: "Schau her! Hier sind die Abteilungen der Priester und Leviten für jeden Dienst im Haus Gottes. Und für jede Arbeit hast du willige und sachkundige Leute zur Seite. Auch die Oberen und das ganze Volk sind bereit für deine Befehle.\"" },
    ] },
    { number: 29, verses: [
      { number: 1, text: "Dann sagte der König zu der ganzen Versammlung: \"Gott hat meinen Sohn Salomo, der noch jung und zart ist, als Einzigen erwählt. Das Werk aber ist groß, denn dieses Bauwerk ist nicht für einen Menschen, sondern für Gott bestimmt, für Jahwe.", heading: "Gaben für den Tempelbau" },
      { number: 2, text: "Ich habe meine ganze Kraft eingesetzt und für das Haus meines Gottes Gold für Goldenes, Silber für Silbernes, Bronze für Bronzenes, Eisen für Eisernes und Holz für Hölzernes bereitgestellt, Onyxsteine mit Einfassungen, Steine zur Verzierung, Mosaiksteine, alle möglichen Edelsteine und Alabastersteine in Massen." },
      { number: 3, text: "Und darüber hinaus, weil mir das Haus meines Gottes am Herzen liegt, gebe ich das Gold und Silber, das ich persönlich besitze, zusätzlich für das Haus meines Gottes, abgesehen von dem, was ich schon für das Haus des Heiligtums bereitgestellt habe:" },
      { number: 4, text: "100 Tonnen Ofirgold und 240 Tonnen* Silber, um die Wände der Bauten zu überziehen,", footnotes: ["100 ... Tonnen. Wörtlich: 3000 Talente Gold und 7000 Talente Silber. Ein Talent entspricht etwa 34,5 Kilogramm."] },
      { number: 5, text: "Gold für das Goldene und Silber für das Silberne und für jede Arbeit von Künstlerhand. Und wer ist nun von euch bereit, Jahwe Gaben zu weihen?\"" },
      { number: 6, text: "Da zeigten die Oberen der Sippen und der Stämme Israels, die Anführer der Tausend- und Hundertschaften und die Oberen im königlichen Dienst ihre Großzügigkeit." },
      { number: 7, text: "Sie gaben für die Arbeit am Haus Gottes 173 Tonnen Gold, 10.000 Goldstücke, 345 Tonnen Silber, 621 Tonnen Bronze und 3450 Tonnen* Eisen.", footnotes: ["173 ... Tonnen. Wörtlich: 5000 Talente Gold, 10.000 Talente Silber, 18.000 Talente Bronze und 100.000 Talente Eisen."] },
      { number: 8, text: "Wer Edelsteine besaß, gab sie in den Schatz vom Haus Jahwes, der von Jehiël, einem Nachkommen Gerschons, verwaltet wurde." },
      { number: 9, text: "Das Volk freute sich über die eigene Spendenbereitschaft, denn von ganzem Herzen spendeten sie für Jahwe. Auch König David war hocherfreut." },
      { number: 10, text: "Und David lobte Jahwe vor der ganzen Versammlung. Er betete: \"Gepriesen seist du, Jahwe, Gott unseres Vaters Israel, von Ewigkeit zu Ewigkeit!", heading: "Davids Dankgebet" },
      { number: 11, text: "Dir, Jahwe, gehören Größe und Kraft, Ehre, Ruhm und Hoheit! Denn alles im Himmel und auf der Erde ist dein. Dir, Jahwe, gehört das Reich, und du bist es, der als Haupt über alles erhoben ist." },
      { number: 12, text: "Reichtum und Ehre kommen von dir, und du bist der Herr über alles. In deiner Hand sind Stärke und Macht, und in deiner Hand liegt es, alles groß und stark zu machen." },
      { number: 13, text: "Und nun, unser Gott, danken wir dir und preisen deinen herrlichen Namen." },
      { number: 14, text: "Denn wer bin ich und was ist mein Volk, dass wir die Kraft haben, so freigebig zu spenden? Denn von dir kommt alles, und aus deiner Hand haben wir dir gegeben." },
      { number: 15, text: "Denn vor dir sind wir Ausländer und Fremde wie alle unsere Vorfahren. Unser Leben auf der Erde vergeht wie ein Schatten, und es gibt keine Hoffnung." },
      { number: 16, text: "Jahwe, unser Gott, all das, was wir bereitgestellt haben, um deinem heiligen Namen ein Haus zu bauen, ist ja aus deiner Hand gekommen. Und das alles gehört dir." },
      { number: 17, text: "Ich weiß, mein Gott, dass du das Herz prüfst, und dass Aufrichtigkeit dir gefällt. Ich habe das alles mit aufrichtigem Herzen gegeben und habe jetzt mit Freude gesehen, dass auch dein hier versammeltes Volk dir bereitwillig gegeben hat." },
      { number: 18, text: "Jahwe, Gott unserer Väter Abraham, Isaak und Israel, erhalte diese Gesinnung für alle Zeiten im Herzen deines Volkes und richte ihre Herzen fest auf dich." },
      { number: 19, text: "Und gib auch meinem Sohn Salomo ein ungeteiltes Herz, dass er deine Gebote, Mahnungen und Ordnungen beachtet und alles ausführt und diesen Tempel baut, den ich vorbereitet habe.\"" },
      { number: 20, text: "David forderte die ganze Versammlung auf: \"Preist doch Jahwe, euren Gott!\" Da pries die ganze Versammlung Jahwe, den Gott ihrer Väter. Sie verneigten sich und ehrten so Gott und den König." },
      { number: 21, text: "Am nächsten Tag brachten sie Jahwe Opfer. Sie schlachteten 1000 Stiere, 1000 Schafböcke und 1000 Lämmer. Dazu kamen die Trankopfer sowie massenhaft Schlachtopfer für ganz Israel.", heading: "Salomos Thronbesteigung" },
      { number: 22, text: "An diesem Tag aßen und tranken sie vor Jahwe mit großer Freude, und zum zweiten Mal riefen sie Salomo Ben-David zum König aus. Vor Jahwe salbten sie ihn zum Fürsten und Zadok zum Priester." },
      { number: 23, text: "So setzte sich Salomo anstelle seines Vaters David als König auf den Thron Jahwes. Und er hatte Erfolg. Ganz Israel hörte auf ihn." },
      { number: 24, text: "Alle Anführer, die Elitetruppe und auch die anderen Söhne von König David unterwarfen sich dem König Salomo." },
      { number: 25, text: "Jahwe machte Salomo überaus groß vor den Augen der Israeliten, er gab ihm eine königliche Hoheit, wie sie kein König vor ihm über Israel hatte." },
      { number: 26, text: "So hatte David Ben-Isai über ganz Israel geherrscht.", heading: "Zusammenfassung der Regierung Davids" },
      { number: 27, text: "Er regierte insgesamt 40 Jahre, sieben Jahre in Hebron und 33 Jahre in Jerusalem." },
      { number: 28, text: "Er starb in einem guten Alter, lebenssatt und satt an Reichtum und Ehre. Sein Sohn Salomo wurde sein Nachfolger." },
      { number: 29, text: "Was sonst noch über David zu sagen ist, seine frühere und spätere Geschichte, findet man in der Chronik des Sehers Samuel, des Propheten Natan und der Geschichte Gads, des Schauenden," },
      { number: 30, text: "zusammen mit der Geschichte seiner ganzen Königsherrschaft, seiner Macht und der Zeiten, die über ihn, über Israel und die anderen Königreiche hingegangen sind." },
    ] },
  ],
};